\":[{\"name\":\"Logical ability\",\"score\":8,\"max\":14,\"correct\":8,\"total\":14},{\"name\":\"Quantitative ability\",\"score\":9,\"max\":16,\"correct\":9,\"total\":16},{\"name\":\"Verbal ability\",\"score\":14,\"max\":22,\"correct\":14,\"total\":22}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Which number is the odd one out: 27, 8, 28, 729?\",\"options\":[\"27\",\"28\",\"8\",\"729\"],\"yourOption\":3,\"correctOption\":1,\"explanation\":\"28 — all others are perfect cubes.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 13, 23, 33, 43, 53, ?\",\"options\":[\"63\",\"56\",\"58\",\"60\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Rule: add 10 each time. Next term = 63.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"11 : 25 :: 7 : ?\",\"options\":[\"20\",\"18\",\"15\",\"17\"],\"yourOption\":1,\"correctOption\":3,\"explanation\":\"The rule is n → 2n + 3; for 7 it gives 17.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"If 2 ⊕ 5 = 29; 6 ⊕ 5 = 61, then 9 ⊕ 5 = ?\",\"options\":[\"93\",\"123\",\"103\",\"106\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"a ⊕ b = a² + b²; so 9 ⊕ 5 = 106.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Isha is 12th from the left and 8th from the right in a row. How many people are in the row?\",\"options\":[\"20\",\"19\",\"21\",\"18\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 12 + 8 − 1 = 19.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Statements: Some phones are chairs. No chairs is pens.\\nConclusion: Some phones are not pens.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion must hold in every possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 3, 13, 43, 133, 403, ?\",\"options\":[\"1076\",\"1213\",\"1285\",\"1086\"],\"correctOption\":1,\"explanation\":\"Rule: multiply by 3 and add 4. Next term = 1213.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Esha is the father of Yash. Yash is the sister of Kavya. How is Esha related to Kavya?\",\"options\":[\"Father\",\"Grandfather\",\"Brother\",\"Uncle\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"Kavya is Yash\'s sibling, so Esha is Kavya\'s father too.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"If 9 ⊕ 6 = 69; 3 ⊕ 8 = 35, then 9 ⊕ 5 = ?\",\"options\":[\"59\",\"52\",\"67\",\"68\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"a ⊕ b = ab + a + b; so 9 ⊕ 5 = 59.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Gita is the mother of Chitra. Meera is the son of Chitra. How is Gita related to Meera?\",\"options\":[\"Grandmother\",\"Mother\",\"Sister\",\"Aunt\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Gita is the mother of Meera\'s parent.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 3, 10, 24, 52, 108, ?\",\"options\":[\"215\",\"218\",\"220\",\"241\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"Rule: multiply by 2 and add 4. Next term = 220.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Bharat is taller than Kavya. Kavya is taller than Rahul. Pooja is taller than Ojas. Rahul is taller than Pooja. Who is the shortest?\",\"options\":[\"Kavya\",\"Bharat\",\"Rahul\",\"Ojas\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"Chaining the clues: Bharat > Kavya > Rahul > Pooja > Ojas. The shortest is Ojas.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 5, 12, 26, 54, 110, ?\",\"options\":[\"225\",\"198\",\"222\",\"227\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Rule: multiply by 2 and add 2. Next term = 222.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next: H, K, N, Q, T, ?\",\"options\":[\"Y\",\"V\",\"X\",\"W\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A train 300 m long passes a pole in 18 seconds. What is its speed in km/h?\",\"options\":[\"60 km/h\",\"50/3 km/h\",\"66 km/h\",\"56 km/h\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"300/18 m/s × 18/5 = 60 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A can finish a work in 40 days and B in 10 days. In how many days will they finish it working together?\",\"options\":[\"8 days\",\"15/2 days\",\"9 days\",\"25 days\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"Together per day: 1/40 + 1/10 = 1/8; time = 8 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"The present ages of A and B are in the ratio 5:3. After 8 years, the ratio will be 7:5. What is A\'s present age?\",\"options\":[\"20 years\",\"12 years\",\"28 years\",\"18 years\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Let ages be 5x and 3x. (5x+8)/(3x+8) = 7/5 gives x = 4; A = 20.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A can finish a work in 24 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"32 days\",\"16 days\",\"29/2 days\",\"15 days\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Together per day: 1/24 + 1/40 = 1/15; time = 15 days.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In what ratio must rice at Rs 30/kg be mixed with rice at Rs 54/kg so that the mixture costs Rs 35/kg?\",\"options\":[\"30:54\",\"19:5\",\"5:19\",\"20:5\"],\"correctOption\":1,\"explanation\":\"Alligation: (cheaper : dearer) = (54 − 35) : (35 − 30) = 19:5.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Two pipes can fill a tank in 8 hours and 24 hours. How long will they take to fill it together?\",\"options\":[\"6 hours\",\"7 hours\",\"11/2 hours\",\"13/2 hours\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"Rate = 1/8 + 1/24 = 1/6; time = 6 hours.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In how many ways can a committee of 3 be chosen from 7 people?\",\"options\":[\"35\",\"210\",\"42\",\"70\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"C(7,3) = 35.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"If today is Wednesday, what day of the week will it be after 294 days?\",\"options\":[\"Thursday\",\"Monday\",\"Tuesday\",\"Wednesday\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"294 mod 7 = 0; Wednesday + 0 days = Wednesday.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A starts a business with Rs 9000. After 6 months B joins with Rs 3000. At the end of the year the profit is Rs 1400. What is B\'s share?\",\"options\":[\"Rs 700\",\"Rs 200\",\"Rs 1200\",\"Rs 350\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Ratio = 9000×12 : 3000×6 = 108000:18000; B gets 1400 × 18000/126000 = Rs 200.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In how many ways can a committee of 3 be chosen from 8 people?\",\"options\":[\"112\",\"64\",\"56\",\"336\"],\"correctOption\":2,\"explanation\":\"C(8,3) = 56.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"What is the compound interest on Rs 16000 at 20% per annum for 2 years, compounded annually?\",\"options\":[\"Rs 7090\",\"Rs 6400\",\"Rs 7040\",\"Rs 7020\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"A = 16000(1 + 20/100)^2 = 23040; CI = A − P = Rs 7040.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Two pipes can fill a tank in 15 hours and 12 hours. How long will they take to fill it together?\",\"options\":[\"20/3 hours\",\"23/3 hours\",\"43/6 hours\",\"37/6 hours\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Rate = 1/15 + 1/12 = 3/20; time = 20/3 hours.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 320 | 245\\n2022 | 280 | 220\\n2023 | 190 | 180\\n2024 | 130 | 85\\n2025 | 120 | 105\\n\\nIn 2024, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"34.62%\",\"65.38%\",\"67.88%\",\"63.63%\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"85/130 × 100 = 65.38%.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A boat goes 26 km downstream in 2 hours and 14 km upstream in 2 hours. What is the speed of the boat in still water?\",\"options\":[\"13 km/h\",\"3 km/h\",\"10 km/h\",\"7 km/h\"],\"correctOption\":2,\"explanation\":\"Downstream 13 km/h, upstream 7 km/h; boat = average = 10 km/h.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"What is 20% of 400?\",\"options\":[\"80\",\"75\",\"71\",\"87\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"20/100 × 400 = 80.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A shopkeeper buys an article for Rs 600 and sells it at a profit of 12%. What is the selling price?\",\"options\":[\"672\",\"630\",\"729\",\"715\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"SP = 600 × (100 + 12)/100 = Rs 672.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘LENIENT’.\",\"options\":[\"lean\",\"tolerant\",\"lethal\",\"lengthy\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"‘lenient’ means tolerant.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘HAMPER’.\",\"options\":[\"help\",\"handle\",\"hinder\",\"hammer\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘hamper’ means hinder; its opposite is ‘help’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: You should ____ your doctor before taking this medicine.\",\"options\":[\"consult\",\"insult\",\"result\",\"exult\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: You should consult your doctor before taking this medicine.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) prefers coffee (C) than (D) tea.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘Prefer … to’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘let the cat out of the bag’ mean?\",\"options\":[\"reveal a secret\",\"free an animal\",\"make a mistake in shopping\",\"go on a trip\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘let the cat out of the bag’ means: reveal a secret.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: A person who has retired from work\",\"options\":[\"trainee\",\"freelancer\",\"pensioner\",\"apprentice\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"A person who has retired from work: pensioner.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘IMMENSE’.\",\"options\":[\"innocent\",\"huge\",\"idle\",\"intense\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"‘immense’ means huge.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘LETHARGIC’.\",\"options\":[\"energetic\",\"sluggish\",\"lethal\",\"legal\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"‘lethargic’ means sluggish; its opposite is ‘energetic’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: She is ____ honest woman.\",\"options\":[\"the\",\"a\",\"an\",\"no article\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Correct: She is an honest woman.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) He did not (B) knew the answer (C) to the last (D) question.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"After ‘did not’ use the base form: ‘know’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘under the weather’ mean?\",\"options\":[\"slightly ill\",\"out in the rain\",\"very happy\",\"worried about the news\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"‘under the weather’ means: slightly ill.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: An animal that eats only plants\",\"options\":[\"herbivore\",\"insectivore\",\"omnivore\",\"carnivore\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"An animal that eats only plants: herbivore.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘CORDIAL’.\",\"options\":[\"warm\",\"careful\",\"central\",\"cordless\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘cordial’ means warm.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘EMINENT’.\",\"options\":[\"empty\",\"unknown\",\"imminent\",\"distinguished\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"‘eminent’ means distinguished; its opposite is ‘unknown’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: He is senior ____ me by two years.\",\"options\":[\"than\",\"over\",\"from\",\"to\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"Correct: He is senior to me by two years.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) I am (B) looking forward (C) to see you (D) soon.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘Looking forward to seeing’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘keep your chin up’ mean?\",\"options\":[\"look at the sky\",\"sit straight\",\"stay positive in difficulty\",\"be proud\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘keep your chin up’ means: stay positive in difficulty.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: A person who does not believe in God\",\"options\":[\"pilgrim\",\"atheist\",\"priest\",\"theist\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who does not believe in God: atheist.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘LETHARGIC’.\",\"options\":[\"literal\",\"sluggish\",\"legal\",\"lethal\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"‘lethargic’ means sluggish.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘AUGMENT’.\",\"options\":[\"reduce\",\"decorate\",\"increase\",\"observe\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"‘augment’ means increase; its opposite is ‘reduce’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: He apologised ____ being late.\",\"options\":[\"for\",\"about\",\"on\",\"of\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: He apologised for being late.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) He is (B) an honest (C) and hardworking (D) man.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":3,\"correctOption\":4,\"explanation\":\"The sentence is correct.\",\"marksAwarded\":0,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-08-23 22:00:00','2026-08-23 23:00:00'),('6e81752e-ef57-47be-8cb9-da974f95dd49','72213566-2c52-4e3d-9fbd-8e841e9040cc','6de4c1e4-b4b9-40f0-ac1d-1e2effb96c41','2026-07-10 12:00:00','2026-11-24 19:37:38','2026-07-10 12:54:00',NULL,NULL,0,0,NULL,50.00,60,'{\"q31\":{\"option\":0},\"q30\":{\"option\":3},\"q33\":{\"option\":0},\"q32\":{\"option\":3},\"q35\":{\"option\":2},\"q34\":{\"option\":1},\"q37\":{\"option\":0},\"q36\":{\"option\":2},\"q39\":{\"option\":3},\"q40\":{\"option\":3},\"q42\":{\"option\":1},\"q41\":{\"option\":2},\"q44\":{\"option\":1},\"q43\":{\"option\":3},\"q46\":{\"option\":2},\"q45\":{\"option\":3},\"q48\":{\"option\":2},\"q47\":{\"option\":1},\"q49\":{\"option\":2},\"q51\":{\"option\":0},\"q50\":{\"option\":2},\"q53\":{\"option\":3},\"q52\":{\"option\":0},\"q11\":{\"option\":0},\"q55\":{\"option\":1},\"q10\":{\"option\":0},\"q13\":{\"option\":2},\"q57\":{\"option\":3},\"q12\":{\"option\":3},\"q56\":{\"option\":0},\"q15\":{\"option\":3},\"q59\":{\"option\":2},\"q14\":{\"option\":2},\"q58\":{\"option\":3},\"q17\":{\"option\":0},\"q16\":{\"option\":1},\"q19\":{\"option\":3},\"q18\":{\"option\":0},\"q1\":{\"option\":3},\"q2\":{\"option\":3},\"q3\":{\"option\":1},\"q4\":{\"option\":0},\"q5\":{\"option\":0},\"q6\":{\"option\":1},\"q7\":{\"option\":3},\"q8\":{\"option\":3},\"q9\":{\"option\":0},\"q60\":{\"option\":2},\"q20\":{\"option\":1},\"q22\":{\"option\":3},\"q24\":{\"option\":1},\"q23\":{\"option\":1},\"q26\":{\"option\":1},\"q25\":{\"option\":0},\"q28\":{\"option\":0},\"q27\":{\"option\":1},\"q29\":{\"option\":1}}',NULL,'{\"attemptId\":\"6e81752e-ef57-47be-8cb9-da974f95dd49\",\"testId\":\"72213566-2c52-4e3d-9fbd-8e841e9040cc\",\"title\":\"HCLTech style · Aptitude + Computer basics\",\"companyTag\":\"HCLTech\",\"startedAt\":\"2026-11-24T18:37:38Z\",\"submittedAt\":\"2026-11-24T18:37:38.057525426Z\",\"timeTakenSeconds\":0,\"score\":50,\"maxScore\":60,\"percent\":83,\"sections\":[{\"name\":\"Quantitative\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15},{\"name\":\"Logical\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15},{\"name\":\"Verbal\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15},{\"name\":\"Computer fundamentals\",\"score\":11,\"max\":15,\"correct\":11,\"total\":15}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 6x + 21 = 99, what is x?\",\"options\":[\"14\",\"11\",\"12\",\"13\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"6x = 78, so x = 13.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A can finish a work in 20 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"30 days\",\"77/6 days\",\"43/3 days\",\"40/3 days\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Together per day: 1/20 + 1/40 = 3/40; time = 40/3 days.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 2:50?\",\"options\":[\"215°\",\"145°\",\"240°\",\"150°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |60 − 275| = 145°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A train 120 m long passes a pole in 9 seconds. What is its speed in km/h?\",\"options\":[\"48 km/h\",\"40/3 km/h\",\"44 km/h\",\"54 km/h\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"120/9 m/s × 18/5 = 48 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A rectangular field is 38 m long and 15 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 1740\",\"Rs 8550\",\"Rs 1590\",\"Rs 795\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"Perimeter = 2(38+15) = 106 m; cost = 106 × 15 = Rs 1590.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 8:20?\",\"options\":[\"135°\",\"130°\",\"120°\",\"230°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |240 − 110| = 130°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 18, 15 and 8 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"41 seconds\",\"180 seconds\",\"720 seconds\",\"360 seconds\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"LCM(18, 15, 8) = 360 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Find the simple interest on Rs 10500 at 6% per annum for 4 years.\",\"options\":[\"Rs 2304\",\"Rs 2369\",\"Rs 2602\",\"Rs 2520\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"SI = P × R × T / 100 = 10500 × 6 × 4 / 100 = Rs 2520.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 6, 18 and 20 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"360 seconds\",\"90 seconds\",\"180 seconds\",\"44 seconds\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"LCM(6, 18, 20) = 180 seconds.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In what ratio must rice at Rs 24/kg be mixed with rice at Rs 72/kg so that the mixture costs Rs 64/kg?\",\"options\":[\"1:5\",\"2:5\",\"24:72\",\"5:1\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Alligation: (cheaper : dearer) = (72 − 64) : (64 − 24) = 1:5.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The price of an item is first increased by 10% and then decreased by 20%. What is the net percentage change in its price?\",\"options\":[\"12% decrease\",\"11% decrease\",\"14% decrease\",\"13% decrease\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Net factor = (1 + 10/100)(1 - 20/100) = 22/25, so the change is -12%: a 12% decrease.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The present ages of A and B are in the ratio 7:5. After 4 years, the ratio will be 25:19. What is A\'s present age?\",\"options\":[\"15 years\",\"25 years\",\"19 years\",\"21 years\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Let ages be 7x and 5x. (7x+4)/(5x+4) = 25/19 gives x = 3; A = 21.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 4x + 29 = 85, what is x?\",\"options\":[\"17\",\"18\",\"14\",\"10\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"4x = 56, so x = 14.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 300 | 280\\n2022 | 250 | 210\\n2023 | 340 | 280\\n2024 | 240 | 190\\n2025 | 130 | 105\\n\\nIn 2023, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"17.65%\",\"84.85%\",\"82.35%\",\"80.6%\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"280/340 × 100 = 82.35%.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In how many ways can a committee of 2 be chosen from 6 people?\",\"options\":[\"12\",\"30\",\"21\",\"15\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"C(6,2) = 15.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 17th from the left and 11th from the right in a row. How many people are in the row?\",\"options\":[\"28\",\"27\",\"26\",\"29\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 17 + 11 − 1 = 27.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: D, F, H, J, L, ?\",\"options\":[\"N\",\"P\",\"O\",\"M\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Each letter moves 2 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Bharat is taller than Kavya. Farhan is taller than Bharat. Jatin is taller than Asha. Kavya is taller than Jatin. Who is the shortest?\",\"options\":[\"Asha\",\"Kavya\",\"Farhan\",\"Bharat\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Chaining the clues: Farhan > Bharat > Kavya > Jatin > Asha. The shortest is Asha.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 21st from the left and 20th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"42\",\"40\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 21 + 20 − 1 = 40.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Yash walks 12 m towards the East, then turns right and walks 5 m, then turns right and walks 12 m. How far is Yash from the starting point?\",\"options\":[\"4 m\",\"8 m\",\"5 m\",\"1 m\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"Net displacement: 0 m east and 5 m south; distance = √(0² + 5²) = 5 m.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some cars are flowers. All flowers are phones.\\nConclusion: All cars are phones.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Nikhil is 18th from the left and 17th from the right in a row. How many people are in the row?\",\"options\":[\"36\",\"33\",\"35\",\"34\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 18 + 17 − 1 = 34.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 31, 27, 1000, 125?\",\"options\":[\"27\",\"31\",\"1000\",\"125\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"31 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"In a class of 83 students, 50 like cricket, 44 like football and 23 like both. How many like neither?\",\"options\":[\"14\",\"12\",\"35\",\"15\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"83 − (50 + 44 − 23) = 12.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 25th from the left and 24th from the right in a row. How many people are in the row?\",\"options\":[\"48\",\"50\",\"47\",\"49\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Total = 25 + 24 − 1 = 48.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: F, J, N, R, V, ?\",\"options\":[\"B\",\"Z\",\"Y\",\"A\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Lokesh is 24th from the left and 16th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"38\",\"40\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 24 + 16 − 1 = 39.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 8, 218, 216, 1000?\",\"options\":[\"218\",\"8\",\"1000\",\"216\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"218 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some teachers are chairs. All chairs are birds.\\nConclusion: All teachers are birds.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"A man is facing North. He turns right, then turns left, then turns about. Which direction is he facing now?\",\"options\":[\"West\",\"North\",\"East\",\"South\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘VIVID’.\",\"options\":[\"bright\",\"honest\",\"rough\",\"late\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘vivid’ means bright.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: The workers went ____ strike yesterday.\",\"options\":[\"at\",\"in\",\"for\",\"on\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Correct: The workers went on strike yesterday.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Unless you (B) do not work hard, (C) you will not (D) succeed.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"‘Unless’ is already negative: ‘work hard’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A speech made without preparation\",\"options\":[\"monologue\",\"extempore\",\"sermon\",\"lecture\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A speech made without preparation: extempore.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘hit the nail on the head’ mean?\",\"options\":[\"make a loud noise\",\"hurt someone badly\",\"describe exactly what is causing a problem\",\"work as a carpenter\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘hit the nail on the head’ means: describe exactly what is causing a problem.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ENIGMATIC’.\",\"options\":[\"energetic\",\"emphatic\",\"mysterious\",\"erratic\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘enigmatic’ means mysterious.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: She is capable ____ handling the pressure.\",\"options\":[\"of\",\"for\",\"at\",\"to\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: She is capable of handling the pressure.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Ten kilometres (B) are (C) a long distance (D) to walk.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"correctOption\":1,\"explanation\":\"A distance as one amount: ‘is’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who is easily deceived\",\"options\":[\"cynical\",\"vigilant\",\"sceptical\",\"gullible\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"A person who is easily deceived: gullible.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘cost an arm and a leg’ mean?\",\"options\":[\"need hard work\",\"cause an injury\",\"be cheap\",\"be very expensive\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘cost an arm and a leg’ means: be very expensive.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ALLEVIATE’.\",\"options\":[\"allocate\",\"allude\",\"relieve\",\"alter\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘alleviate’ means relieve.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: No sooner did she arrive ____ the lights went out.\",\"options\":[\"that\",\"than\",\"when\",\"then\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Correct: No sooner did she arrive than the lights went out.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) has (C) a lot of (D) knowledges.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘Knowledge’ is uncountable: ‘knowledge’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who spends very little\",\"options\":[\"philanthropist\",\"miser\",\"spendthrift\",\"donor\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who spends very little: miser.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘a drop in the ocean’ mean?\",\"options\":[\"a heavy rain\",\"a sea voyage\",\"a big mistake\",\"a very small amount compared to what is needed\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘a drop in the ocean’ means: a very small amount compared to what is needed.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What does ‘len([1, [2, 3], 4])’ return in Python?\",\"options\":[\"Error\",\"4\",\"3\",\"2\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The nested list counts as one element.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which device forwards frames using MAC addresses?\",\"options\":[\"Router\",\"Switch\",\"Modem\",\"Hub\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Switches work at layer 2.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"The difference between a process and a thread is that threads\",\"options\":[\"have separate address spaces\",\"always run on different machines\",\"share the memory of their process\",\"cannot run in parallel\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Threads of one process share its address space.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which scheduling algorithm can cause starvation of long jobs?\",\"options\":[\"First Come First Served\",\"Round Robin\",\"Shortest Job First\",\"Multilevel with ageing\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Short jobs keep jumping ahead.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Microservices architecture means\",\"options\":[\"an app built as small independently deployable services\",\"a database type\",\"only front-end code\",\"one large deployable unit\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"Each service owns one capability.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which traversal uses a stack (explicitly or via recursion)?\",\"options\":[\"Depth-first search\",\"Level-order traversal\",\"Dijkstra with a queue\",\"Breadth-first search\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"DFS goes deep first.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ACID properties of transactions are\",\"options\":[\"Atomicity, Consistency, Isolation, Durability\",\"Accuracy, Concurrency, Integrity, Durability\",\"Atomicity, Concurrency, Isolation, Dependency\",\"Availability, Consistency, Isolation, Durability\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Standard transaction guarantees.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q53\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which testing checks individual functions in isolation?\",\"options\":[\"System testing\",\"Acceptance testing\",\"Load testing\",\"Unit testing\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Smallest testable parts.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q54\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In MS Excel, which function adds a range of cells?\",\"options\":[\"TOTAL\",\"ADD\",\"SUM\",\"COUNT\"],\"correctOption\":2,\"explanation\":\"=SUM(A1:A10).\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q55\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Cloud model where you rent virtual machines and manage the OS yourself:\",\"options\":[\"SaaS\",\"IaaS\",\"PaaS\",\"FaaS\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Infrastructure as a Service.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q56\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Gmail is an example of\",\"options\":[\"On-premise software\",\"SaaS\",\"IaaS\",\"PaaS\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Software delivered over the internet.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q57\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In C, the size of ‘char’ is\",\"options\":[\"2 bytes\",\"depends on the compiler always 8 bytes\",\"4 bytes\",\"1 byte\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"char is defined as one byte.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q58\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What is a deadlock?\",\"options\":[\"Memory that cannot be freed\",\"A crashed disk\",\"A process that finishes early\",\"Processes waiting forever for resources held by each other\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Circular wait among processes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q59\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which normal form removes partial dependencies on a composite key?\",\"options\":[\"2NF\",\"BCNF\",\"3NF\",\"1NF\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"2NF requires full functional dependency on the whole key.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q60\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ARP is used to find\",\"options\":[\"the IP for a domain\",\"open ports\",\"the MAC address for an IP address\",\"the fastest route\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Address Resolution Protocol.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-07-10 12:00:00','2026-07-10 13:00:00'),('6ecbfc3e-8e96-4024-8555-36cf7388fd06','b5d64ac3-c6dd-4d00-8968-44ca21685a31','5f71e5da-65a0-4f0b-a8c2-3483898534cc','2026-08-19 22:00:00','2026-11-24 20:12:43','2026-08-19 22:52:00',NULL,NULL,0,0,NULL,52.00,75,'{\"q71\":{\"option\":2},\"q70\":{\"option\":2},\"q73\":{\"option\":1},\"q72\":{\"option\":2},\"q31\":{\"option\":2},\"q75\":{\"option\":2},\"q74\":{\"option\":0},\"q33\":{\"option\":2},\"q32\":{\"option\":3},\"q34\":{\"option\":2},\"q37\":{\"option\":0},\"q36\":{\"option\":3},\"q39\":{\"option\":2},\"q38\":{\"option\":2},\"q40\":{\"option\":0},\"q42\":{\"option\":0},\"q41\":{\"option\":2},\"q44\":{\"option\":2},\"q43\":{\"option\":2},\"q46\":{\"option\":1},\"q45\":{\"option\":1},\"q48\":{\"option\":0},\"q47\":{\"option\":3},\"q49\":{\"option\":2},\"q51\":{\"option\":1},\"q50\":{\"option\":1},\"q53\":{\"option\":0},\"q52\":{\"option\":0},\"q11\":{\"option\":3},\"q10\":{\"option\":2},\"q54\":{\"option\":2},\"q13\":{\"option\":0},\"q12\":{\"option\":3},\"q56\":{\"option\":3},\"q15\":{\"option\":2},\"q59\":{\"option\":0},\"q14\":{\"option\":3},\"q58\":{\"option\":0},\"q16\":{\"option\":2},\"q19\":{\"option\":1},\"q18\":{\"option\":2},\"q1\":{\"option\":0},\"q2\":{\"option\":1},\"q3\":{\"option\":0},\"q4\":{\"option\":0},\"q6\":{\"option\":1},\"q7\":{\"option\":3},\"q8\":{\"option\":2},\"q9\":{\"option\":3},\"q60\":{\"option\":2},\"q62\":{\"option\":3},\"q61\":{\"option\":3},\"q20\":{\"option\":3},\"q64\":{\"option\":1},\"q63\":{\"option\":2},\"q22\":{\"option\":3},\"q66\":{\"option\":2},\"q65\":{\"option\":0},\"q24\":{\"option\":3},\"q68\":{\"option\":0},\"q23\":{\"option\":1},\"q67\":{\"option\":1},\"q26\":{\"option\":2},\"q25\":{\"option\":2},\"q69\":{\"option\":0},\"q28\":{\"option\":2},\"q27\":{\"option\":0},\"q29\":{\"option\":1}}',NULL,'{\"attemptId\":\"6ecbfc3e-8e96-4024-8555-36cf7388fd06\",\"testId\":\"b5d64ac3-c6dd-4d00-8968-44ca21685a31\",\"title\":\"Cognizant GenC style · Aptitude\",\"companyTag\":\"Cognizant\",\"startedAt\":\"2026-11-24T18:37:43Z\",\"submittedAt\":\"2026-11-24T18:37:43.043899009Z\",\"timeTakenSeconds\":0,\"score\":52,\"maxScore\":75,\"percent\":69,\"sections\":[{\"name\":\"Quantitative aptitude\",\"score\":18,\"max\":25,\"correct\":18,\"total\":25},{\"name\":\"Logical reasoning\",\"score\":15,\"max\":25,\"correct\":15,\"total\":25},{\"name\":\"English comprehension\",\"score\":19,\"max\":25,\"correct\":19,\"total\":25}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 8:30?\",\"options\":[\"75°\",\"60°\",\"80°\",\"285°\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Angle = |30H − 5.5M| = |240 − 165| = 75°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"Two dice are thrown together. What is the probability that the sum is 8?\",\"options\":[\"1/9\",\"5/36\",\"5/12\",\"1/6\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"5 favourable outcomes out of 36: 5/36.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"What is the sum of the first 32 terms of the series 5, 13, 21, ...?\",\"options\":[\"8096\",\"4384\",\"4128\",\"4123\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"S = n/2 [2a + (n−1)d] = 32/2 × [10 + 248] = 4128.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A shopkeeper buys an article for Rs 1600 and sells it at a profit of 10%. What is the selling price?\",\"options\":[\"1760\",\"1837\",\"1876\",\"1692\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"SP = 1600 × (100 + 10)/100 = Rs 1760.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 360 | 320\\n2022 | 220 | 145\\n2023 | 140 | 130\\n2024 | 300 | 270\\n2025 | 260 | 235\\n\\nIn 2022, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"64.16%\",\"65.91%\",\"68.41%\",\"34.09%\"],\"correctOption\":1,\"explanation\":\"145/220 × 100 = 65.91%.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A rectangular field is 33 m long and 22 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 10890\",\"Rs 1650\",\"Rs 1800\",\"Rs 825\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Perimeter = 2(33+22) = 110 m; cost = 110 × 15 = Rs 1650.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A train 100 m long passes a pole in 18 seconds. What is its speed in km/h?\",\"options\":[\"26 km/h\",\"16 km/h\",\"50/9 km/h\",\"20 km/h\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"100/18 m/s × 18/5 = 20 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"If 6x + 4 = 64, what is x?\",\"options\":[\"13\",\"7\",\"10\",\"9\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"6x = 60, so x = 10.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A rectangular field is 37 m long and 16 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 8880\",\"Rs 1740\",\"Rs 795\",\"Rs 1590\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Perimeter = 2(37+16) = 106 m; cost = 106 × 15 = Rs 1590.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"3 bells ring at intervals of 4, 6 and 24 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"48 seconds\",\"34 seconds\",\"24 seconds\",\"12 seconds\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"LCM(4, 6, 24) = 24 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 160 | 150\\n2022 | 130 | 90\\n2023 | 310 | 275\\n2024 | 350 | 280\\n2025 | 180 | 150\\n\\nIn 2024, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"82.5%\",\"78.25%\",\"80%\",\"20%\"],\"yourOption\":3,\"correctOption\":2,\"explanation\":\"280/350 × 100 = 80.0%.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"The present ages of A and B are in the ratio 7:5. After 10 years, the ratio will be 19:15. What is A\'s present age?\",\"options\":[\"38 years\",\"20 years\",\"26 years\",\"28 years\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Let ages be 7x and 5x. (7x+10)/(5x+10) = 19/15 gives x = 4; A = 28.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"The price of an item is first increased by 25% and then decreased by 25%. What is the net percentage change in its price?\",\"options\":[\"25/4% decrease\",\"21/4% decrease\",\"29/4% decrease\",\"33/4% decrease\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Net factor = (1 + 25/100)(1 - 25/100) = 15/16, so the change is -25/4%: a 25/4% decrease.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A train 200 m long passes a pole in 12 seconds. What is its speed in km/h?\",\"options\":[\"60 km/h\",\"56 km/h\",\"66 km/h\",\"50/3 km/h\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"200/12 m/s × 18/5 = 60 km/h.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A starts a business with Rs 5000. After 3 months B joins with Rs 9000. At the end of the year the profit is Rs 4700. What is B\'s share?\",\"options\":[\"Rs 21150/7\",\"Rs 3200\",\"Rs 2700\",\"Rs 2000\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Ratio = 5000×12 : 9000×9 = 60000:81000; B gets 4700 × 81000/141000 = Rs 2700.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"What is 10% of 840?\",\"options\":[\"70\",\"91\",\"84\",\"82\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"10/100 × 840 = 84.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"The present ages of A and B are in the ratio 2:1. After 4 years, the ratio will be 22:13. What is A\'s present age?\",\"options\":[\"18 years\",\"16 years\",\"22 years\",\"9 years\"],\"correctOption\":0,\"explanation\":\"Let ages be 2x and 1x. (2x+4)/(1x+4) = 22/13 gives x = 9; A = 18.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"Two pipes can fill a tank in 10 hours and 30 hours. How long will they take to fill it together?\",\"options\":[\"8 hours\",\"7 hours\",\"15/2 hours\",\"17/2 hours\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Rate = 1/10 + 1/30 = 2/15; time = 15/2 hours.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A shopkeeper buys an article for Rs 1400 and sells it at a profit of 12%. What is the selling price?\",\"options\":[\"1556\",\"1568\",\"1438\",\"1612\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"SP = 1400 × (100 + 12)/100 = Rs 1568.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A shopkeeper buys an article for Rs 350 and sells it at a profit of 12%. What is the selling price?\",\"options\":[\"429\",\"404\",\"372\",\"392\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"SP = 350 × (100 + 12)/100 = Rs 392.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"Find the simple interest on Rs 2000 at 10% per annum for 3 years.\",\"options\":[\"Rs 658\",\"Rs 600\",\"Rs 616\",\"Rs 715\"],\"correctOption\":1,\"explanation\":\"SI = P × R × T / 100 = 2000 × 10 × 3 / 100 = Rs 600.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"If today is Sunday, what day of the week will it be after 77 days?\",\"options\":[\"Monday\",\"Tuesday\",\"Wednesday\",\"Sunday\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"77 mod 7 = 0; Sunday + 0 days = Sunday.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"A shopkeeper buys an article for Rs 1200 and sells it at a profit of 20%. What is the selling price?\",\"options\":[\"1321\",\"1440\",\"1468\",\"1411\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"SP = 1200 × (100 + 20)/100 = Rs 1440.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"3 bells ring at intervals of 10, 6 and 12 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"120 seconds\",\"28 seconds\",\"30 seconds\",\"60 seconds\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"LCM(10, 6, 12) = 60 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Quantitative aptitude\",\"text\":\"The average of 5 numbers is 59. If one more number, 89, is added, what is the new average?\",\"options\":[\"61\",\"67\",\"65\",\"64\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"New sum = 59×5 + 89 = 384; ÷ 6 = 64.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next in the series: 6, 18, 54, 162, 486, ?\",\"options\":[\"1561\",\"1510\",\"1458\",\"1418\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Rule: multiply by 3 each time. Next term = 1458.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"In a class of 56 students, 21 like cricket, 36 like football and 8 like both. How many like neither?\",\"options\":[\"15\",\"9\",\"10\",\"7\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"56 − (21 + 36 − 8) = 7.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"In a certain code, SCHOOL is written as TDIPPM. How is TICKET written in that code?\",\"options\":[\"TICKET\",\"WLFNHW\",\"UJDLFU\",\"VKEMGV\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Each letter is shifted +1 place in the alphabet.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next in the series: 3, 7, 15, 31, 63, ?\",\"options\":[\"115\",\"127\",\"114\",\"119\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Rule: multiply by 2 and add 1. Next term = 127.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: E, I, M, Q, U, ?\",\"options\":[\"X\",\"Z\",\"Y\",\"A\"],\"correctOption\":2,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"8 : 512 :: 6 : ?\",\"options\":[\"180\",\"250\",\"216\",\"198\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The rule is n → n³; for 6 it gives 216.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"In a class of 83 students, 58 like cricket, 39 like football and 27 like both. How many like neither?\",\"options\":[\"40\",\"16\",\"15\",\"13\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"83 − (58 + 39 − 27) = 13.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"Which number is the odd one out: 512, 217, 64, 216?\",\"options\":[\"64\",\"216\",\"512\",\"217\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"217 — all others are perfect cubes.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"9 : 90 :: 7 : ?\",\"options\":[\"56\",\"47\",\"55\",\"50\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"The rule is n → n² + n; for 7 it gives 56.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"Isha is taller than Asha. Tarun is taller than Isha. Lokesh is taller than Dev. Asha is taller than Lokesh. Who is the tallest?\",\"options\":[\"Isha\",\"Asha\",\"Tarun\",\"Lokesh\"],\"correctOption\":2,\"explanation\":\"Chaining the clues: Tarun > Isha > Asha > Lokesh > Dev. The tallest is Tarun.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: I, L, O, R, U, ?\",\"options\":[\"X\",\"W\",\"Z\",\"Y\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"Statements: All chairs are rivers. All rivers are flowers.\\nConclusion: All chairs are flowers.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion must hold in every possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: A, D, G, J, M, ?\",\"options\":[\"P\",\"O\",\"Q\",\"R\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"In a class of 61 students, 27 like cricket, 41 like football and 19 like both. How many like neither?\",\"options\":[\"12\",\"15\",\"31\",\"14\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"61 − (27 + 41 − 19) = 12.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"7 : 17 :: 3 : ?\",\"options\":[\"9\",\"8\",\"12\",\"10\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"The rule is n → 2n + 3; for 3 it gives 9.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"A man is facing South. He turns left, then turns about, then turns left. Which direction is he facing now?\",\"options\":[\"North\",\"East\",\"South\",\"West\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"If 2 ⊕ 3 = 3; 5 ⊕ 9 = 21, then 4 ⊕ 7 = ?\",\"options\":[\"9\",\"13\",\"17\",\"11\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"a ⊕ b = (a − b)² + a; so 4 ⊕ 7 = 13.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"If 7 ⊕ 6 = 8; 5 ⊕ 7 = 9, then 4 ⊕ 3 = ?\",\"options\":[\"1\",\"5\",\"4\",\"2\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"a ⊕ b = (a − b)² + a; so 4 ⊕ 3 = 5.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: B, F, J, N, R, ?\",\"options\":[\"W\",\"U\",\"V\",\"X\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"A man is facing South. He turns right, then turns left, then turns left, then turns right. Which direction is he facing now?\",\"options\":[\"North\",\"South\",\"East\",\"West\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"In a class of 75 students, 52 like cricket, 41 like football and 22 like both. How many like neither?\",\"options\":[\"6\",\"4\",\"26\",\"7\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"75 − (52 + 41 − 22) = 4.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: F, I, L, O, R, ?\",\"options\":[\"V\",\"T\",\"W\",\"U\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"If 7 ⊕ 8 = 8; 2 ⊕ 5 = 11, then 3 ⊕ 9 = ?\",\"options\":[\"39\",\"34\",\"45\",\"36\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"a ⊕ b = (a − b)² + a; so 3 ⊕ 9 = 39.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"What comes next: K, N, Q, T, W, ?\",\"options\":[\"A\",\"Y\",\"Z\",\"B\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Logical reasoning\",\"text\":\"A man is facing South. He turns right, then turns about. Which direction is he facing now?\",\"options\":[\"South\",\"East\",\"West\",\"North\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: East.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Read the passage and answer.\\n\\nRemote work was once rare in Indian companies. The pandemic forced firms to try it at scale, and many found that productivity did not fall. Employees saved hours of commuting, and companies saved on office space. However, new problems appeared: junior staff missed informal learning from seniors, and some people found it hard to separate work from home life. Many firms have now settled on a hybrid model, with two or three office days a week.\\n\\nThe tone of the passage is best described as\",\"options\":[\"angry\",\"balanced\",\"fearful\",\"humorous\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"The passage supports: balanced.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Fill in the blank: The police ____ arrested the thief.\",\"options\":[\"have\",\"has\",\"was\",\"is\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: The police have arrested the thief.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q53\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) If he would have (B) studied (C) he would have (D) passed.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Third conditional: ‘If he had studied’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q54\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word closest in meaning to ‘CONCEAL’.\",\"options\":[\"repair\",\"conceive\",\"hide\",\"reject\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘conceal’ means hide.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q55\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘EXACERBATE’.\",\"options\":[\"excavate\",\"exaggerate\",\"worsen\",\"improve\"],\"correctOption\":3,\"explanation\":\"‘exacerbate’ means worsen; its opposite is ‘improve’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q56\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Read the passage and answer.\\n\\nGood sleep is essential for learning. While we sleep, the brain sorts and stores what we learned during the day. Students who stay up all night before an exam often remember less than those who sleep well, even if they studied for more hours. Regular sleep times, less screen use before bed and a dark, quiet room all improve sleep quality.\\n\\nWhat does the brain do during sleep, according to the passage?\",\"options\":[\"Forgets the day\'s events\",\"Stops all activity\",\"Plans the next day\",\"Sorts and stores what was learned\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"The passage supports: Sorts and stores what was learned.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q57\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Fill in the blank: There is ____ water left in the bottle.\",\"options\":[\"a few of\",\"many\",\"few\",\"little\"],\"correctOption\":3,\"explanation\":\"Correct: There is little water left in the bottle.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q58\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) The number of students (B) in the class (C) are increasing (D) every year.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"Subject is ‘the number’: ‘is increasing’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q59\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word closest in meaning to ‘COGENT’.\",\"options\":[\"convincing\",\"costly\",\"cognate\",\"collective\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘cogent’ means convincing.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q60\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘BREVITY’.\",\"options\":[\"shortness\",\"beauty\",\"lengthiness\",\"bravery\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘brevity’ means shortness; its opposite is ‘lengthiness’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q61\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Read the passage and answer.\\n\\nMany rivers in India are fed by Himalayan glaciers. As temperatures rise, these glaciers are shrinking. In the short term this can increase river flow and the risk of floods; in the long term, rivers may carry less water in dry months. Scientists stress the need to monitor glaciers and to plan water use carefully.\\n\\nScientists stress the need to\",\"options\":[\"build more glaciers\",\"stop all farming\",\"ignore river flow\",\"monitor glaciers and plan water use\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"The passage supports: monitor glaciers and plan water use.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q62\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Fill in the blank: Each of the students ____ given a prize.\",\"options\":[\"were\",\"have been\",\"are\",\"was\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Correct: Each of the students was given a prize.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q63\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) My brother (B) and I (C) am going (D) to the fair.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Compound subject: ‘are going’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q64\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word closest in meaning to ‘VALIANT’.\",\"options\":[\"valuable\",\"vague\",\"brave\",\"vacant\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"‘valiant’ means brave.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q65\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘PERTINENT’.\",\"options\":[\"irrelevant\",\"persistent\",\"pertinacious\",\"relevant\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘pertinent’ means relevant; its opposite is ‘irrelevant’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q66\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Read the passage and answer.\\n\\nPlastic is cheap, light and durable, which is why it is everywhere. The same durability makes it a problem: most plastic takes hundreds of years to break down. Much of it ends up in rivers and oceans, where it harms animals that swallow it or get trapped. Recycling helps, but only a small share of plastic is actually recycled. Experts say the most effective step is to use less plastic in the first place.\\n\\nThe word ‘durable’ in the passage means\",\"options\":[\"cheap\",\"dangerous\",\"long-lasting\",\"flexible\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The passage supports: long-lasting.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q67\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Fill in the blank: She has been working here ____ 2019.\",\"options\":[\"by\",\"since\",\"for\",\"from\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Correct: She has been working here since 2019.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q68\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) The doctor (B) advised him (C) to give up (D) smoking.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":0,\"correctOption\":4,\"explanation\":\"The sentence is correct.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q69\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word closest in meaning to ‘RESILIENT’.\",\"options\":[\"tough\",\"reluctant\",\"resident\",\"relevant\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘resilient’ means tough.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q70\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘SERENE’.\",\"options\":[\"sincere\",\"calm\",\"chaotic\",\"severe\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘serene’ means calm; its opposite is ‘chaotic’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q71\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Read the passage and answer.\\n\\nOpen-source software is written by communities and shared freely. Anyone can read the code, suggest changes or report bugs. Because many people review it, problems are often found quickly. Companies use open-source tools to save costs and avoid being locked to one vendor, and many pay their engineers to contribute back.\\n\\nWhat is true of open-source software?\",\"options\":[\"Its code is secret\",\"Only one company can change it\",\"Anyone can read the code\",\"It must be bought\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The passage supports: Anyone can read the code.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q72\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Fill in the blank: She objected ____ his rude remarks.\",\"options\":[\"against\",\"at\",\"on\",\"to\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"Correct: She objected to his rude remarks.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q73\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Between you (B) and I, (C) this plan (D) will fail.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Object pronoun after a preposition: ‘and me’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q74\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word closest in meaning to ‘METICULOUS’.\",\"options\":[\"careful\",\"hollow\",\"angry\",\"famous\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘meticulous’ means careful.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q75\",\"type\":\"MCQ\",\"section\":\"English comprehension\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘LAVISH’.\",\"options\":[\"lavender\",\"lawful\",\"meagre\",\"luxurious\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘lavish’ means luxurious; its opposite is ‘meagre’.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-08-19 22:00:00','2026-08-19 23:00:00'),('6f1f8fb1-1b3a-4131-85a4-acbbfa0f01da','617d3dc4-3697-4d65-9404-ccd3c0b8ede3','5afea5a7-15c2-45f0-8cfb-85ffd910ee51','2026-03-27 09:00:00','2026-11-24 19:25:30','2026-03-27 09:42:00',NULL,NULL,0,0,NULL,33.00,52,'{\"q51\":{\"option\":0},\"q50\":{\"option\":3},\"q31\":{\"option\":3},\"q30\":{\"option\":3},\"q52\":{\"option\":4},\"q33\":{\"option\":0},\"q10\":{\"option\":0},\"q32\":{\"option\":0},\"q13\":{\"option\":0},\"q35\":{\"option\":0},\"q12\":{\"option\":3},\"q34\":{\"option\":2},\"q15\":{\"option\":1},\"q37\":{\"option\":1},\"q14\":{\"option\":3},\"q17\":{\"option\":1},\"q39\":{\"option\":3},\"q16\":{\"option\":2},\"q38\":{\"option\":0},\"q18\":{\"option\":1},\"q1\":{\"option\":1},\"q2\":{\"option\":0},\"q3\":{\"option\":0},\"q4\":{\"option\":3},\"q5\":{\"option\":1},\"q6\":{\"option\":1},\"q7\":{\"option\":1},\"q8\":{\"option\":0},\"q9\":{\"option\":1},\"q40\":{\"option\":1},\"q20\":{\"option\":0},\"q42\":{\"option\":0},\"q41\":{\"option\":0},\"q44\":{\"option\":1},\"q21\":{\"option\":0},\"q43\":{\"option\":0},\"q24\":{\"option\":2},\"q46\":{\"option\":2},\"q23\":{\"option\":1},\"q45\":{\"option\":3},\"q26\":{\"option\":0},\"q48\":{\"option\":1},\"q25\":{\"option\":2},\"q47\":{\"option\":2},\"q27\":{\"option\":2},\"q49\":{\"option\":2},\"q29\":{\"option\":0}}',NULL,'{\"attemptId\":\"6f1f8fb1-1b3a-4131-85a4-acbbfa0f01da\",\"testId\":\"617d3dc4-3697-4d65-9404-ccd3c0b8ede3\",\"title\":\"Wipro NLTH style · Aptitude\",\"companyTag\":\"Wipro\",\"startedAt\":\"2026-11-24T18:37:30Z\",\"submittedAt\":\"2026-11-24T18:37:30.139016290Z\",\"timeTakenSeconds\":0,\"score\":33,\"maxScore\":52,\"percent\":63,\"sections\":[{\"name\":\"Logical ability\",\"score\":9,\"max\":14,\"correct\":9,\"total\":14},{\"name\":\"Quantitative ability\",\"score\":7,\"max\":16,\"correct\":7,\"total\":16},{\"name\":\"Verbal ability\",\"score\":17,\"max\":22,\"correct\":17,\"total\":22}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Which number is the odd one out: 27, 8, 28, 729?\",\"options\":[\"27\",\"28\",\"8\",\"729\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"28 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 13, 23, 33, 43, 53, ?\",\"options\":[\"63\",\"56\",\"58\",\"60\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Rule: add 10 each time. Next term = 63.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"11 : 25 :: 7 : ?\",\"options\":[\"20\",\"18\",\"15\",\"17\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"The rule is n → 2n + 3; for 7 it gives 17.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"If 2 ⊕ 5 = 29; 6 ⊕ 5 = 61, then 9 ⊕ 5 = ?\",\"options\":[\"93\",\"123\",\"103\",\"106\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"a ⊕ b = a² + b²; so 9 ⊕ 5 = 106.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Isha is 12th from the left and 8th from the right in a row. How many people are in the row?\",\"options\":[\"20\",\"19\",\"21\",\"18\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 12 + 8 − 1 = 19.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Statements: Some phones are chairs. No chairs is pens.\\nConclusion: Some phones are not pens.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion must hold in every possible case.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 3, 13, 43, 133, 403, ?\",\"options\":[\"1076\",\"1213\",\"1285\",\"1086\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Rule: multiply by 3 and add 4. Next term = 1213.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Esha is the father of Yash. Yash is the sister of Kavya. How is Esha related to Kavya?\",\"options\":[\"Father\",\"Grandfather\",\"Brother\",\"Uncle\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Kavya is Yash\'s sibling, so Esha is Kavya\'s father too.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"If 9 ⊕ 6 = 69; 3 ⊕ 8 = 35, then 9 ⊕ 5 = ?\",\"options\":[\"59\",\"52\",\"67\",\"68\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"a ⊕ b = ab + a + b; so 9 ⊕ 5 = 59.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Gita is the mother of Chitra. Meera is the son of Chitra. How is Gita related to Meera?\",\"options\":[\"Grandmother\",\"Mother\",\"Sister\",\"Aunt\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Gita is the mother of Meera\'s parent.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 3, 10, 24, 52, 108, ?\",\"options\":[\"215\",\"218\",\"220\",\"241\"],\"correctOption\":2,\"explanation\":\"Rule: multiply by 2 and add 4. Next term = 220.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"Bharat is taller than Kavya. Kavya is taller than Rahul. Pooja is taller than Ojas. Rahul is taller than Pooja. Who is the shortest?\",\"options\":[\"Kavya\",\"Bharat\",\"Rahul\",\"Ojas\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Chaining the clues: Bharat > Kavya > Rahul > Pooja > Ojas. The shortest is Ojas.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next in the series: 5, 12, 26, 54, 110, ?\",\"options\":[\"225\",\"198\",\"222\",\"227\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"Rule: multiply by 2 and add 2. Next term = 222.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Logical ability\",\"text\":\"What comes next: H, K, N, Q, T, ?\",\"options\":[\"Y\",\"V\",\"X\",\"W\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Each letter moves 3 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A train 300 m long passes a pole in 18 seconds. What is its speed in km/h?\",\"options\":[\"60 km/h\",\"50/3 km/h\",\"66 km/h\",\"56 km/h\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"300/18 m/s × 18/5 = 60 km/h.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A can finish a work in 40 days and B in 10 days. In how many days will they finish it working together?\",\"options\":[\"8 days\",\"15/2 days\",\"9 days\",\"25 days\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"Together per day: 1/40 + 1/10 = 1/8; time = 8 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"The present ages of A and B are in the ratio 5:3. After 8 years, the ratio will be 7:5. What is A\'s present age?\",\"options\":[\"20 years\",\"12 years\",\"28 years\",\"18 years\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"Let ages be 5x and 3x. (5x+8)/(3x+8) = 7/5 gives x = 4; A = 20.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A can finish a work in 24 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"32 days\",\"16 days\",\"29/2 days\",\"15 days\"],\"yourOption\":1,\"correctOption\":3,\"explanation\":\"Together per day: 1/24 + 1/40 = 1/15; time = 15 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In what ratio must rice at Rs 30/kg be mixed with rice at Rs 54/kg so that the mixture costs Rs 35/kg?\",\"options\":[\"30:54\",\"19:5\",\"5:19\",\"20:5\"],\"correctOption\":1,\"explanation\":\"Alligation: (cheaper : dearer) = (54 − 35) : (35 − 30) = 19:5.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Two pipes can fill a tank in 8 hours and 24 hours. How long will they take to fill it together?\",\"options\":[\"6 hours\",\"7 hours\",\"11/2 hours\",\"13/2 hours\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Rate = 1/8 + 1/24 = 1/6; time = 6 hours.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In how many ways can a committee of 3 be chosen from 7 people?\",\"options\":[\"35\",\"210\",\"42\",\"70\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"C(7,3) = 35.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"If today is Wednesday, what day of the week will it be after 294 days?\",\"options\":[\"Thursday\",\"Monday\",\"Tuesday\",\"Wednesday\"],\"correctOption\":3,\"explanation\":\"294 mod 7 = 0; Wednesday + 0 days = Wednesday.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A starts a business with Rs 9000. After 6 months B joins with Rs 3000. At the end of the year the profit is Rs 1400. What is B\'s share?\",\"options\":[\"Rs 700\",\"Rs 200\",\"Rs 1200\",\"Rs 350\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Ratio = 9000×12 : 3000×6 = 108000:18000; B gets 1400 × 18000/126000 = Rs 200.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"In how many ways can a committee of 3 be chosen from 8 people?\",\"options\":[\"112\",\"64\",\"56\",\"336\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"C(8,3) = 56.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"What is the compound interest on Rs 16000 at 20% per annum for 2 years, compounded annually?\",\"options\":[\"Rs 7090\",\"Rs 6400\",\"Rs 7040\",\"Rs 7020\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"A = 16000(1 + 20/100)^2 = 23040; CI = A − P = Rs 7040.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Two pipes can fill a tank in 15 hours and 12 hours. How long will they take to fill it together?\",\"options\":[\"20/3 hours\",\"23/3 hours\",\"43/6 hours\",\"37/6 hours\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Rate = 1/15 + 1/12 = 3/20; time = 20/3 hours.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 320 | 245\\n2022 | 280 | 220\\n2023 | 190 | 180\\n2024 | 130 | 85\\n2025 | 120 | 105\\n\\nIn 2024, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"34.62%\",\"65.38%\",\"67.88%\",\"63.63%\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"85/130 × 100 = 65.38%.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A boat goes 26 km downstream in 2 hours and 14 km upstream in 2 hours. What is the speed of the boat in still water?\",\"options\":[\"13 km/h\",\"3 km/h\",\"10 km/h\",\"7 km/h\"],\"correctOption\":2,\"explanation\":\"Downstream 13 km/h, upstream 7 km/h; boat = average = 10 km/h.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"What is 20% of 400?\",\"options\":[\"80\",\"75\",\"71\",\"87\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"20/100 × 400 = 80.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Quantitative ability\",\"text\":\"A shopkeeper buys an article for Rs 600 and sells it at a profit of 12%. What is the selling price?\",\"options\":[\"672\",\"630\",\"729\",\"715\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"SP = 600 × (100 + 12)/100 = Rs 672.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘LENIENT’.\",\"options\":[\"lean\",\"tolerant\",\"lethal\",\"lengthy\"],\"yourOption\":3,\"correctOption\":1,\"explanation\":\"‘lenient’ means tolerant.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘HAMPER’.\",\"options\":[\"help\",\"handle\",\"hinder\",\"hammer\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘hamper’ means hinder; its opposite is ‘help’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: You should ____ your doctor before taking this medicine.\",\"options\":[\"consult\",\"insult\",\"result\",\"exult\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: You should consult your doctor before taking this medicine.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) prefers coffee (C) than (D) tea.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘Prefer … to’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘let the cat out of the bag’ mean?\",\"options\":[\"reveal a secret\",\"free an animal\",\"make a mistake in shopping\",\"go on a trip\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘let the cat out of the bag’ means: reveal a secret.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: A person who has retired from work\",\"options\":[\"trainee\",\"freelancer\",\"pensioner\",\"apprentice\"],\"correctOption\":2,\"explanation\":\"A person who has retired from work: pensioner.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘IMMENSE’.\",\"options\":[\"innocent\",\"huge\",\"idle\",\"intense\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"‘immense’ means huge.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘LETHARGIC’.\",\"options\":[\"energetic\",\"sluggish\",\"lethal\",\"legal\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘lethargic’ means sluggish; its opposite is ‘energetic’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: She is ____ honest woman.\",\"options\":[\"the\",\"a\",\"an\",\"no article\"],\"yourOption\":3,\"correctOption\":2,\"explanation\":\"Correct: She is an honest woman.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) He did not (B) knew the answer (C) to the last (D) question.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"After ‘did not’ use the base form: ‘know’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘under the weather’ mean?\",\"options\":[\"slightly ill\",\"out in the rain\",\"very happy\",\"worried about the news\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘under the weather’ means: slightly ill.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: An animal that eats only plants\",\"options\":[\"herbivore\",\"insectivore\",\"omnivore\",\"carnivore\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"An animal that eats only plants: herbivore.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘CORDIAL’.\",\"options\":[\"warm\",\"careful\",\"central\",\"cordless\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘cordial’ means warm.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘EMINENT’.\",\"options\":[\"empty\",\"unknown\",\"imminent\",\"distinguished\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"‘eminent’ means distinguished; its opposite is ‘unknown’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: He is senior ____ me by two years.\",\"options\":[\"than\",\"over\",\"from\",\"to\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Correct: He is senior to me by two years.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) I am (B) looking forward (C) to see you (D) soon.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘Looking forward to seeing’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"What does the idiom ‘keep your chin up’ mean?\",\"options\":[\"look at the sky\",\"sit straight\",\"stay positive in difficulty\",\"be proud\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘keep your chin up’ means: stay positive in difficulty.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"One word for: A person who does not believe in God\",\"options\":[\"pilgrim\",\"atheist\",\"priest\",\"theist\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who does not believe in God: atheist.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word closest in meaning to ‘LETHARGIC’.\",\"options\":[\"literal\",\"sluggish\",\"legal\",\"lethal\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"‘lethargic’ means sluggish.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Choose the word most nearly OPPOSITE in meaning to ‘AUGMENT’.\",\"options\":[\"reduce\",\"decorate\",\"increase\",\"observe\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"‘augment’ means increase; its opposite is ‘reduce’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Fill in the blank: He apologised ____ being late.\",\"options\":[\"for\",\"about\",\"on\",\"of\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: He apologised for being late.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Verbal ability\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) He is (B) an honest (C) and hardworking (D) man.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":4,\"correctOption\":4,\"explanation\":\"The sentence is correct.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-03-27 09:00:00','2026-03-27 10:00:00'),('7009115e-4149-438c-b091-9141bb9f7977','72213566-2c52-4e3d-9fbd-8e841e9040cc','8b005729-91c1-40aa-96ab-f45ff15a6832','2026-05-15 19:00:00','2026-11-24 19:37:46','2026-05-15 19:51:00',NULL,NULL,0,0,NULL,44.00,60,'{\"q31\":{\"option\":0},\"q30\":{\"option\":3},\"q32\":{\"option\":3},\"q35\":{\"option\":2},\"q34\":{\"option\":2},\"q37\":{\"option\":0},\"q36\":{\"option\":2},\"q39\":{\"option\":3},\"q38\":{\"option\":4},\"q40\":{\"option\":3},\"q42\":{\"option\":0},\"q41\":{\"option\":2},\"q44\":{\"option\":1},\"q43\":{\"option\":3},\"q46\":{\"option\":1},\"q45\":{\"option\":3},\"q48\":{\"option\":2},\"q47\":{\"option\":1},\"q49\":{\"option\":1},\"q51\":{\"option\":0},\"q50\":{\"option\":0},\"q53\":{\"option\":3},\"q52\":{\"option\":0},\"q11\":{\"option\":0},\"q55\":{\"option\":1},\"q10\":{\"option\":0},\"q54\":{\"option\":2},\"q13\":{\"option\":0},\"q57\":{\"option\":0},\"q12\":{\"option\":3},\"q15\":{\"option\":3},\"q59\":{\"option\":0},\"q14\":{\"option\":2},\"q58\":{\"option\":3},\"q16\":{\"option\":1},\"q19\":{\"option\":3},\"q18\":{\"option\":3},\"q1\":{\"option\":3},\"q2\":{\"option\":2},\"q3\":{\"option\":1},\"q4\":{\"option\":0},\"q5\":{\"option\":2},\"q6\":{\"option\":1},\"q7\":{\"option\":2},\"q8\":{\"option\":3},\"q9\":{\"option\":2},\"q60\":{\"option\":2},\"q20\":{\"option\":0},\"q22\":{\"option\":2},\"q21\":{\"option\":1},\"q24\":{\"option\":1},\"q23\":{\"option\":1},\"q26\":{\"option\":1},\"q25\":{\"option\":0},\"q28\":{\"option\":0},\"q27\":{\"option\":1},\"q29\":{\"option\":0}}',NULL,'{\"attemptId\":\"7009115e-4149-438c-b091-9141bb9f7977\",\"testId\":\"72213566-2c52-4e3d-9fbd-8e841e9040cc\",\"title\":\"HCLTech style · Aptitude + Computer basics\",\"companyTag\":\"HCLTech\",\"startedAt\":\"2026-11-24T18:37:46Z\",\"submittedAt\":\"2026-11-24T18:37:46.228235907Z\",\"timeTakenSeconds\":0,\"score\":44,\"maxScore\":60,\"percent\":73,\"sections\":[{\"name\":\"Quantitative\",\"score\":12,\"max\":15,\"correct\":12,\"total\":15},{\"name\":\"Logical\",\"score\":10,\"max\":15,\"correct\":10,\"total\":15},{\"name\":\"Verbal\",\"score\":11,\"max\":15,\"correct\":11,\"total\":15},{\"name\":\"Computer fundamentals\",\"score\":11,\"max\":15,\"correct\":11,\"total\":15}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 6x + 21 = 99, what is x?\",\"options\":[\"14\",\"11\",\"12\",\"13\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"6x = 78, so x = 13.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A can finish a work in 20 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"30 days\",\"77/6 days\",\"43/3 days\",\"40/3 days\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"Together per day: 1/20 + 1/40 = 3/40; time = 40/3 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 2:50?\",\"options\":[\"215°\",\"145°\",\"240°\",\"150°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |60 − 275| = 145°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A train 120 m long passes a pole in 9 seconds. What is its speed in km/h?\",\"options\":[\"48 km/h\",\"40/3 km/h\",\"44 km/h\",\"54 km/h\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"120/9 m/s × 18/5 = 48 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A rectangular field is 38 m long and 15 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 1740\",\"Rs 8550\",\"Rs 1590\",\"Rs 795\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Perimeter = 2(38+15) = 106 m; cost = 106 × 15 = Rs 1590.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 8:20?\",\"options\":[\"135°\",\"130°\",\"120°\",\"230°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |240 − 110| = 130°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 18, 15 and 8 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"41 seconds\",\"180 seconds\",\"720 seconds\",\"360 seconds\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"LCM(18, 15, 8) = 360 seconds.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Find the simple interest on Rs 10500 at 6% per annum for 4 years.\",\"options\":[\"Rs 2304\",\"Rs 2369\",\"Rs 2602\",\"Rs 2520\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"SI = P × R × T / 100 = 10500 × 6 × 4 / 100 = Rs 2520.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 6, 18 and 20 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"360 seconds\",\"90 seconds\",\"180 seconds\",\"44 seconds\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"LCM(6, 18, 20) = 180 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In what ratio must rice at Rs 24/kg be mixed with rice at Rs 72/kg so that the mixture costs Rs 64/kg?\",\"options\":[\"1:5\",\"2:5\",\"24:72\",\"5:1\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Alligation: (cheaper : dearer) = (72 − 64) : (64 − 24) = 1:5.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The price of an item is first increased by 10% and then decreased by 20%. What is the net percentage change in its price?\",\"options\":[\"12% decrease\",\"11% decrease\",\"14% decrease\",\"13% decrease\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Net factor = (1 + 10/100)(1 - 20/100) = 22/25, so the change is -12%: a 12% decrease.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The present ages of A and B are in the ratio 7:5. After 4 years, the ratio will be 25:19. What is A\'s present age?\",\"options\":[\"15 years\",\"25 years\",\"19 years\",\"21 years\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Let ages be 7x and 5x. (7x+4)/(5x+4) = 25/19 gives x = 3; A = 21.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 4x + 29 = 85, what is x?\",\"options\":[\"17\",\"18\",\"14\",\"10\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"4x = 56, so x = 14.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 300 | 280\\n2022 | 250 | 210\\n2023 | 340 | 280\\n2024 | 240 | 190\\n2025 | 130 | 105\\n\\nIn 2023, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"17.65%\",\"84.85%\",\"82.35%\",\"80.6%\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"280/340 × 100 = 82.35%.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In how many ways can a committee of 2 be chosen from 6 people?\",\"options\":[\"12\",\"30\",\"21\",\"15\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"C(6,2) = 15.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 17th from the left and 11th from the right in a row. How many people are in the row?\",\"options\":[\"28\",\"27\",\"26\",\"29\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 17 + 11 − 1 = 27.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: D, F, H, J, L, ?\",\"options\":[\"N\",\"P\",\"O\",\"M\"],\"correctOption\":0,\"explanation\":\"Each letter moves 2 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Bharat is taller than Kavya. Farhan is taller than Bharat. Jatin is taller than Asha. Kavya is taller than Jatin. Who is the shortest?\",\"options\":[\"Asha\",\"Kavya\",\"Farhan\",\"Bharat\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"Chaining the clues: Farhan > Bharat > Kavya > Jatin > Asha. The shortest is Asha.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 21st from the left and 20th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"42\",\"40\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 21 + 20 − 1 = 40.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Yash walks 12 m towards the East, then turns right and walks 5 m, then turns right and walks 12 m. How far is Yash from the starting point?\",\"options\":[\"4 m\",\"8 m\",\"5 m\",\"1 m\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"Net displacement: 0 m east and 5 m south; distance = √(0² + 5²) = 5 m.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some cars are flowers. All flowers are phones.\\nConclusion: All cars are phones.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Nikhil is 18th from the left and 17th from the right in a row. How many people are in the row?\",\"options\":[\"36\",\"33\",\"35\",\"34\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"Total = 18 + 17 − 1 = 34.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 31, 27, 1000, 125?\",\"options\":[\"27\",\"31\",\"1000\",\"125\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"31 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"In a class of 83 students, 50 like cricket, 44 like football and 23 like both. How many like neither?\",\"options\":[\"14\",\"12\",\"35\",\"15\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"83 − (50 + 44 − 23) = 12.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 25th from the left and 24th from the right in a row. How many people are in the row?\",\"options\":[\"48\",\"50\",\"47\",\"49\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Total = 25 + 24 − 1 = 48.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: F, J, N, R, V, ?\",\"options\":[\"B\",\"Z\",\"Y\",\"A\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Lokesh is 24th from the left and 16th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"38\",\"40\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 24 + 16 − 1 = 39.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 8, 218, 216, 1000?\",\"options\":[\"218\",\"8\",\"1000\",\"216\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"218 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some teachers are chairs. All chairs are birds.\\nConclusion: All teachers are birds.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"A man is facing North. He turns right, then turns left, then turns about. Which direction is he facing now?\",\"options\":[\"West\",\"North\",\"East\",\"South\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘VIVID’.\",\"options\":[\"bright\",\"honest\",\"rough\",\"late\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘vivid’ means bright.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: The workers went ____ strike yesterday.\",\"options\":[\"at\",\"in\",\"for\",\"on\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Correct: The workers went on strike yesterday.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Unless you (B) do not work hard, (C) you will not (D) succeed.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"correctOption\":1,\"explanation\":\"‘Unless’ is already negative: ‘work hard’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A speech made without preparation\",\"options\":[\"monologue\",\"extempore\",\"sermon\",\"lecture\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"A speech made without preparation: extempore.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘hit the nail on the head’ mean?\",\"options\":[\"make a loud noise\",\"hurt someone badly\",\"describe exactly what is causing a problem\",\"work as a carpenter\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘hit the nail on the head’ means: describe exactly what is causing a problem.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ENIGMATIC’.\",\"options\":[\"energetic\",\"emphatic\",\"mysterious\",\"erratic\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘enigmatic’ means mysterious.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: She is capable ____ handling the pressure.\",\"options\":[\"of\",\"for\",\"at\",\"to\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: She is capable of handling the pressure.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Ten kilometres (B) are (C) a long distance (D) to walk.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":4,\"correctOption\":1,\"explanation\":\"A distance as one amount: ‘is’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who is easily deceived\",\"options\":[\"cynical\",\"vigilant\",\"sceptical\",\"gullible\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"A person who is easily deceived: gullible.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘cost an arm and a leg’ mean?\",\"options\":[\"need hard work\",\"cause an injury\",\"be cheap\",\"be very expensive\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘cost an arm and a leg’ means: be very expensive.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ALLEVIATE’.\",\"options\":[\"allocate\",\"allude\",\"relieve\",\"alter\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘alleviate’ means relieve.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: No sooner did she arrive ____ the lights went out.\",\"options\":[\"that\",\"than\",\"when\",\"then\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Correct: No sooner did she arrive than the lights went out.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) has (C) a lot of (D) knowledges.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘Knowledge’ is uncountable: ‘knowledge’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who spends very little\",\"options\":[\"philanthropist\",\"miser\",\"spendthrift\",\"donor\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who spends very little: miser.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘a drop in the ocean’ mean?\",\"options\":[\"a heavy rain\",\"a sea voyage\",\"a big mistake\",\"a very small amount compared to what is needed\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘a drop in the ocean’ means: a very small amount compared to what is needed.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What does ‘len([1, [2, 3], 4])’ return in Python?\",\"options\":[\"Error\",\"4\",\"3\",\"2\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"The nested list counts as one element.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which device forwards frames using MAC addresses?\",\"options\":[\"Router\",\"Switch\",\"Modem\",\"Hub\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Switches work at layer 2.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"The difference between a process and a thread is that threads\",\"options\":[\"have separate address spaces\",\"always run on different machines\",\"share the memory of their process\",\"cannot run in parallel\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Threads of one process share its address space.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which scheduling algorithm can cause starvation of long jobs?\",\"options\":[\"First Come First Served\",\"Round Robin\",\"Shortest Job First\",\"Multilevel with ageing\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"Short jobs keep jumping ahead.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Microservices architecture means\",\"options\":[\"an app built as small independently deployable services\",\"a database type\",\"only front-end code\",\"one large deployable unit\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Each service owns one capability.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which traversal uses a stack (explicitly or via recursion)?\",\"options\":[\"Depth-first search\",\"Level-order traversal\",\"Dijkstra with a queue\",\"Breadth-first search\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"DFS goes deep first.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ACID properties of transactions are\",\"options\":[\"Atomicity, Consistency, Isolation, Durability\",\"Accuracy, Concurrency, Integrity, Durability\",\"Atomicity, Concurrency, Isolation, Dependency\",\"Availability, Consistency, Isolation, Durability\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Standard transaction guarantees.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q53\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which testing checks individual functions in isolation?\",\"options\":[\"System testing\",\"Acceptance testing\",\"Load testing\",\"Unit testing\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Smallest testable parts.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q54\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In MS Excel, which function adds a range of cells?\",\"options\":[\"TOTAL\",\"ADD\",\"SUM\",\"COUNT\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"=SUM(A1:A10).\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q55\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Cloud model where you rent virtual machines and manage the OS yourself:\",\"options\":[\"SaaS\",\"IaaS\",\"PaaS\",\"FaaS\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Infrastructure as a Service.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q56\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Gmail is an example of\",\"options\":[\"On-premise software\",\"SaaS\",\"IaaS\",\"PaaS\"],\"correctOption\":1,\"explanation\":\"Software delivered over the internet.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q57\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In C, the size of ‘char’ is\",\"options\":[\"2 bytes\",\"depends on the compiler always 8 bytes\",\"4 bytes\",\"1 byte\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"char is defined as one byte.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q58\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What is a deadlock?\",\"options\":[\"Memory that cannot be freed\",\"A crashed disk\",\"A process that finishes early\",\"Processes waiting forever for resources held by each other\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Circular wait among processes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q59\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which normal form removes partial dependencies on a composite key?\",\"options\":[\"2NF\",\"BCNF\",\"3NF\",\"1NF\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"2NF requires full functional dependency on the whole key.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q60\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ARP is used to find\",\"options\":[\"the IP for a domain\",\"open ports\",\"the MAC address for an IP address\",\"the fastest route\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Address Resolution Protocol.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-05-15 19:00:00','2026-05-15 20:00:00');
INSERT INTO `prep_attempts` (`id`, `test_id`, `user_id`, `started_at`, `deadline_at`, `submitted_at`, `auto_submit_reason`, `consent_at`, `ai_warning_count`, `extra_minutes`, `review_status`, `score`, `max_score`, `answers_json`, `layout_json`, `result_json`, `created_at`, `updated_at`) VALUES ('707a9706-825e-406b-917e-4f97589dbdb4','72213566-2c52-4e3d-9fbd-8e841e9040cc','1c5d9201-0991-4802-bfb0-a497365ace4b','2026-02-19 13:00:00','2026-11-24 19:37:28','2026-02-19 13:39:00',NULL,NULL,0,0,NULL,44.00,60,'{\"q31\":{\"option\":1},\"q30\":{\"option\":3},\"q33\":{\"option\":1},\"q32\":{\"option\":3},\"q35\":{\"option\":1},\"q34\":{\"option\":1},\"q37\":{\"option\":0},\"q36\":{\"option\":2},\"q39\":{\"option\":3},\"q38\":{\"option\":1},\"q40\":{\"option\":3},\"q41\":{\"option\":1},\"q44\":{\"option\":1},\"q43\":{\"option\":2},\"q46\":{\"option\":2},\"q45\":{\"option\":3},\"q48\":{\"option\":2},\"q47\":{\"option\":2},\"q49\":{\"option\":2},\"q51\":{\"option\":0},\"q50\":{\"option\":0},\"q53\":{\"option\":3},\"q52\":{\"option\":0},\"q11\":{\"option\":0},\"q55\":{\"option\":1},\"q10\":{\"option\":0},\"q54\":{\"option\":2},\"q13\":{\"option\":1},\"q57\":{\"option\":3},\"q12\":{\"option\":3},\"q56\":{\"option\":0},\"q15\":{\"option\":3},\"q59\":{\"option\":0},\"q14\":{\"option\":2},\"q58\":{\"option\":3},\"q17\":{\"option\":2},\"q16\":{\"option\":1},\"q19\":{\"option\":3},\"q18\":{\"option\":3},\"q1\":{\"option\":2},\"q4\":{\"option\":0},\"q5\":{\"option\":2},\"q6\":{\"option\":1},\"q7\":{\"option\":3},\"q8\":{\"option\":0},\"q9\":{\"option\":2},\"q60\":{\"option\":2},\"q20\":{\"option\":2},\"q22\":{\"option\":3},\"q21\":{\"option\":0},\"q24\":{\"option\":1},\"q23\":{\"option\":1},\"q25\":{\"option\":0},\"q28\":{\"option\":0},\"q27\":{\"option\":1},\"q29\":{\"option\":1}}',NULL,'{\"attemptId\":\"707a9706-825e-406b-917e-4f97589dbdb4\",\"testId\":\"72213566-2c52-4e3d-9fbd-8e841e9040cc\",\"title\":\"HCLTech style · Aptitude + Computer basics\",\"companyTag\":\"HCLTech\",\"startedAt\":\"2026-11-24T18:37:28Z\",\"submittedAt\":\"2026-11-24T18:37:28.259811035Z\",\"timeTakenSeconds\":0,\"score\":44,\"maxScore\":60,\"percent\":73,\"sections\":[{\"name\":\"Quantitative\",\"score\":10,\"max\":15,\"correct\":10,\"total\":15},{\"name\":\"Logical\",\"score\":11,\"max\":15,\"correct\":11,\"total\":15},{\"name\":\"Verbal\",\"score\":10,\"max\":15,\"correct\":10,\"total\":15},{\"name\":\"Computer fundamentals\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 6x + 21 = 99, what is x?\",\"options\":[\"14\",\"11\",\"12\",\"13\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"6x = 78, so x = 13.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A can finish a work in 20 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"30 days\",\"77/6 days\",\"43/3 days\",\"40/3 days\"],\"correctOption\":3,\"explanation\":\"Together per day: 1/20 + 1/40 = 3/40; time = 40/3 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 2:50?\",\"options\":[\"215°\",\"145°\",\"240°\",\"150°\"],\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |60 − 275| = 145°.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A train 120 m long passes a pole in 9 seconds. What is its speed in km/h?\",\"options\":[\"48 km/h\",\"40/3 km/h\",\"44 km/h\",\"54 km/h\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"120/9 m/s × 18/5 = 48 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A rectangular field is 38 m long and 15 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 1740\",\"Rs 8550\",\"Rs 1590\",\"Rs 795\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Perimeter = 2(38+15) = 106 m; cost = 106 × 15 = Rs 1590.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 8:20?\",\"options\":[\"135°\",\"130°\",\"120°\",\"230°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |240 − 110| = 130°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 18, 15 and 8 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"41 seconds\",\"180 seconds\",\"720 seconds\",\"360 seconds\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"LCM(18, 15, 8) = 360 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Find the simple interest on Rs 10500 at 6% per annum for 4 years.\",\"options\":[\"Rs 2304\",\"Rs 2369\",\"Rs 2602\",\"Rs 2520\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"SI = P × R × T / 100 = 10500 × 6 × 4 / 100 = Rs 2520.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 6, 18 and 20 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"360 seconds\",\"90 seconds\",\"180 seconds\",\"44 seconds\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"LCM(6, 18, 20) = 180 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In what ratio must rice at Rs 24/kg be mixed with rice at Rs 72/kg so that the mixture costs Rs 64/kg?\",\"options\":[\"1:5\",\"2:5\",\"24:72\",\"5:1\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Alligation: (cheaper : dearer) = (72 − 64) : (64 − 24) = 1:5.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The price of an item is first increased by 10% and then decreased by 20%. What is the net percentage change in its price?\",\"options\":[\"12% decrease\",\"11% decrease\",\"14% decrease\",\"13% decrease\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Net factor = (1 + 10/100)(1 - 20/100) = 22/25, so the change is -12%: a 12% decrease.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The present ages of A and B are in the ratio 7:5. After 4 years, the ratio will be 25:19. What is A\'s present age?\",\"options\":[\"15 years\",\"25 years\",\"19 years\",\"21 years\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Let ages be 7x and 5x. (7x+4)/(5x+4) = 25/19 gives x = 3; A = 21.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 4x + 29 = 85, what is x?\",\"options\":[\"17\",\"18\",\"14\",\"10\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"4x = 56, so x = 14.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 300 | 280\\n2022 | 250 | 210\\n2023 | 340 | 280\\n2024 | 240 | 190\\n2025 | 130 | 105\\n\\nIn 2023, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"17.65%\",\"84.85%\",\"82.35%\",\"80.6%\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"280/340 × 100 = 82.35%.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In how many ways can a committee of 2 be chosen from 6 people?\",\"options\":[\"12\",\"30\",\"21\",\"15\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"C(6,2) = 15.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 17th from the left and 11th from the right in a row. How many people are in the row?\",\"options\":[\"28\",\"27\",\"26\",\"29\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 17 + 11 − 1 = 27.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: D, F, H, J, L, ?\",\"options\":[\"N\",\"P\",\"O\",\"M\"],\"yourOption\":2,\"correctOption\":0,\"explanation\":\"Each letter moves 2 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Bharat is taller than Kavya. Farhan is taller than Bharat. Jatin is taller than Asha. Kavya is taller than Jatin. Who is the shortest?\",\"options\":[\"Asha\",\"Kavya\",\"Farhan\",\"Bharat\"],\"yourOption\":3,\"correctOption\":0,\"explanation\":\"Chaining the clues: Farhan > Bharat > Kavya > Jatin > Asha. The shortest is Asha.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 21st from the left and 20th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"42\",\"40\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 21 + 20 − 1 = 40.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Yash walks 12 m towards the East, then turns right and walks 5 m, then turns right and walks 12 m. How far is Yash from the starting point?\",\"options\":[\"4 m\",\"8 m\",\"5 m\",\"1 m\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Net displacement: 0 m east and 5 m south; distance = √(0² + 5²) = 5 m.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some cars are flowers. All flowers are phones.\\nConclusion: All cars are phones.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Nikhil is 18th from the left and 17th from the right in a row. How many people are in the row?\",\"options\":[\"36\",\"33\",\"35\",\"34\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 18 + 17 − 1 = 34.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 31, 27, 1000, 125?\",\"options\":[\"27\",\"31\",\"1000\",\"125\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"31 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"In a class of 83 students, 50 like cricket, 44 like football and 23 like both. How many like neither?\",\"options\":[\"14\",\"12\",\"35\",\"15\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"83 − (50 + 44 − 23) = 12.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 25th from the left and 24th from the right in a row. How many people are in the row?\",\"options\":[\"48\",\"50\",\"47\",\"49\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Total = 25 + 24 − 1 = 48.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: F, J, N, R, V, ?\",\"options\":[\"B\",\"Z\",\"Y\",\"A\"],\"correctOption\":1,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Lokesh is 24th from the left and 16th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"38\",\"40\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 24 + 16 − 1 = 39.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 8, 218, 216, 1000?\",\"options\":[\"218\",\"8\",\"1000\",\"216\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"218 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some teachers are chairs. All chairs are birds.\\nConclusion: All teachers are birds.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"A man is facing North. He turns right, then turns left, then turns about. Which direction is he facing now?\",\"options\":[\"West\",\"North\",\"East\",\"South\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘VIVID’.\",\"options\":[\"bright\",\"honest\",\"rough\",\"late\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"‘vivid’ means bright.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: The workers went ____ strike yesterday.\",\"options\":[\"at\",\"in\",\"for\",\"on\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Correct: The workers went on strike yesterday.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Unless you (B) do not work hard, (C) you will not (D) succeed.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"‘Unless’ is already negative: ‘work hard’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A speech made without preparation\",\"options\":[\"monologue\",\"extempore\",\"sermon\",\"lecture\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A speech made without preparation: extempore.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘hit the nail on the head’ mean?\",\"options\":[\"make a loud noise\",\"hurt someone badly\",\"describe exactly what is causing a problem\",\"work as a carpenter\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"‘hit the nail on the head’ means: describe exactly what is causing a problem.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ENIGMATIC’.\",\"options\":[\"energetic\",\"emphatic\",\"mysterious\",\"erratic\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘enigmatic’ means mysterious.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: She is capable ____ handling the pressure.\",\"options\":[\"of\",\"for\",\"at\",\"to\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: She is capable of handling the pressure.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Ten kilometres (B) are (C) a long distance (D) to walk.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A distance as one amount: ‘is’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who is easily deceived\",\"options\":[\"cynical\",\"vigilant\",\"sceptical\",\"gullible\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"A person who is easily deceived: gullible.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘cost an arm and a leg’ mean?\",\"options\":[\"need hard work\",\"cause an injury\",\"be cheap\",\"be very expensive\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘cost an arm and a leg’ means: be very expensive.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ALLEVIATE’.\",\"options\":[\"allocate\",\"allude\",\"relieve\",\"alter\"],\"yourOption\":1,\"correctOption\":2,\"explanation\":\"‘alleviate’ means relieve.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: No sooner did she arrive ____ the lights went out.\",\"options\":[\"that\",\"than\",\"when\",\"then\"],\"correctOption\":1,\"explanation\":\"Correct: No sooner did she arrive than the lights went out.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) has (C) a lot of (D) knowledges.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"‘Knowledge’ is uncountable: ‘knowledge’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who spends very little\",\"options\":[\"philanthropist\",\"miser\",\"spendthrift\",\"donor\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who spends very little: miser.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘a drop in the ocean’ mean?\",\"options\":[\"a heavy rain\",\"a sea voyage\",\"a big mistake\",\"a very small amount compared to what is needed\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘a drop in the ocean’ means: a very small amount compared to what is needed.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What does ‘len([1, [2, 3], 4])’ return in Python?\",\"options\":[\"Error\",\"4\",\"3\",\"2\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The nested list counts as one element.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which device forwards frames using MAC addresses?\",\"options\":[\"Router\",\"Switch\",\"Modem\",\"Hub\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"Switches work at layer 2.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"The difference between a process and a thread is that threads\",\"options\":[\"have separate address spaces\",\"always run on different machines\",\"share the memory of their process\",\"cannot run in parallel\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Threads of one process share its address space.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which scheduling algorithm can cause starvation of long jobs?\",\"options\":[\"First Come First Served\",\"Round Robin\",\"Shortest Job First\",\"Multilevel with ageing\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Short jobs keep jumping ahead.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Microservices architecture means\",\"options\":[\"an app built as small independently deployable services\",\"a database type\",\"only front-end code\",\"one large deployable unit\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Each service owns one capability.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which traversal uses a stack (explicitly or via recursion)?\",\"options\":[\"Depth-first search\",\"Level-order traversal\",\"Dijkstra with a queue\",\"Breadth-first search\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"DFS goes deep first.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ACID properties of transactions are\",\"options\":[\"Atomicity, Consistency, Isolation, Durability\",\"Accuracy, Concurrency, Integrity, Durability\",\"Atomicity, Concurrency, Isolation, Dependency\",\"Availability, Consistency, Isolation, Durability\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Standard transaction guarantees.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q53\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which testing checks individual functions in isolation?\",\"options\":[\"System testing\",\"Acceptance testing\",\"Load testing\",\"Unit testing\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Smallest testable parts.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q54\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In MS Excel, which function adds a range of cells?\",\"options\":[\"TOTAL\",\"ADD\",\"SUM\",\"COUNT\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"=SUM(A1:A10).\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q55\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Cloud model where you rent virtual machines and manage the OS yourself:\",\"options\":[\"SaaS\",\"IaaS\",\"PaaS\",\"FaaS\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Infrastructure as a Service.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q56\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Gmail is an example of\",\"options\":[\"On-premise software\",\"SaaS\",\"IaaS\",\"PaaS\"],\"yourOption\":0,\"correctOption\":1,\"explanation\":\"Software delivered over the internet.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q57\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In C, the size of ‘char’ is\",\"options\":[\"2 bytes\",\"depends on the compiler always 8 bytes\",\"4 bytes\",\"1 byte\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"char is defined as one byte.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q58\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What is a deadlock?\",\"options\":[\"Memory that cannot be freed\",\"A crashed disk\",\"A process that finishes early\",\"Processes waiting forever for resources held by each other\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Circular wait among processes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q59\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which normal form removes partial dependencies on a composite key?\",\"options\":[\"2NF\",\"BCNF\",\"3NF\",\"1NF\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"2NF requires full functional dependency on the whole key.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q60\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ARP is used to find\",\"options\":[\"the IP for a domain\",\"open ports\",\"the MAC address for an IP address\",\"the fastest route\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Address Resolution Protocol.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-02-19 13:00:00','2026-02-19 14:00:00'),('708d9357-baf5-4d3c-b227-a51a143a376c','72213566-2c52-4e3d-9fbd-8e841e9040cc','97e892f8-0248-4b9d-b104-c77d59402910','2026-01-22 23:00:00','2026-11-24 19:37:37','2026-01-22 23:23:00',NULL,NULL,0,0,NULL,47.00,60,'{\"q31\":{\"option\":0},\"q33\":{\"option\":2},\"q32\":{\"option\":2},\"q34\":{\"option\":1},\"q37\":{\"option\":0},\"q36\":{\"option\":0},\"q39\":{\"option\":3},\"q38\":{\"option\":1},\"q42\":{\"option\":1},\"q41\":{\"option\":2},\"q44\":{\"option\":1},\"q43\":{\"option\":3},\"q46\":{\"option\":2},\"q45\":{\"option\":3},\"q47\":{\"option\":1},\"q49\":{\"option\":2},\"q51\":{\"option\":0},\"q50\":{\"option\":0},\"q53\":{\"option\":3},\"q52\":{\"option\":0},\"q11\":{\"option\":0},\"q55\":{\"option\":1},\"q10\":{\"option\":1},\"q54\":{\"option\":2},\"q13\":{\"option\":2},\"q57\":{\"option\":3},\"q12\":{\"option\":3},\"q56\":{\"option\":1},\"q15\":{\"option\":3},\"q14\":{\"option\":2},\"q58\":{\"option\":3},\"q16\":{\"option\":1},\"q19\":{\"option\":3},\"q18\":{\"option\":0},\"q1\":{\"option\":3},\"q2\":{\"option\":0},\"q3\":{\"option\":1},\"q4\":{\"option\":0},\"q5\":{\"option\":2},\"q6\":{\"option\":1},\"q7\":{\"option\":3},\"q8\":{\"option\":3},\"q9\":{\"option\":2},\"q60\":{\"option\":2},\"q20\":{\"option\":2},\"q21\":{\"option\":1},\"q24\":{\"option\":2},\"q23\":{\"option\":1},\"q26\":{\"option\":1},\"q25\":{\"option\":0},\"q28\":{\"option\":0},\"q27\":{\"option\":1},\"q29\":{\"option\":1}}',NULL,'{\"attemptId\":\"708d9357-baf5-4d3c-b227-a51a143a376c\",\"testId\":\"72213566-2c52-4e3d-9fbd-8e841e9040cc\",\"title\":\"HCLTech style · Aptitude + Computer basics\",\"companyTag\":\"HCLTech\",\"startedAt\":\"2026-11-24T18:37:37Z\",\"submittedAt\":\"2026-11-24T18:37:37.322495530Z\",\"timeTakenSeconds\":0,\"score\":47,\"maxScore\":60,\"percent\":78,\"sections\":[{\"name\":\"Quantitative\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15},{\"name\":\"Logical\",\"score\":11,\"max\":15,\"correct\":11,\"total\":15},{\"name\":\"Verbal\",\"score\":10,\"max\":15,\"correct\":10,\"total\":15},{\"name\":\"Computer fundamentals\",\"score\":13,\"max\":15,\"correct\":13,\"total\":15}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 6x + 21 = 99, what is x?\",\"options\":[\"14\",\"11\",\"12\",\"13\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"6x = 78, so x = 13.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q2\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A can finish a work in 20 days and B in 40 days. In how many days will they finish it working together?\",\"options\":[\"30 days\",\"77/6 days\",\"43/3 days\",\"40/3 days\"],\"yourOption\":0,\"correctOption\":3,\"explanation\":\"Together per day: 1/20 + 1/40 = 3/40; time = 40/3 days.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q3\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 2:50?\",\"options\":[\"215°\",\"145°\",\"240°\",\"150°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |60 − 275| = 145°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q4\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A train 120 m long passes a pole in 9 seconds. What is its speed in km/h?\",\"options\":[\"48 km/h\",\"40/3 km/h\",\"44 km/h\",\"54 km/h\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"120/9 m/s × 18/5 = 48 km/h.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q5\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"A rectangular field is 38 m long and 15 m wide. What is the cost of fencing it at Rs 15 per metre?\",\"options\":[\"Rs 1740\",\"Rs 8550\",\"Rs 1590\",\"Rs 795\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Perimeter = 2(38+15) = 106 m; cost = 106 × 15 = Rs 1590.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q6\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 8:20?\",\"options\":[\"135°\",\"130°\",\"120°\",\"230°\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Angle = |30H − 5.5M| = |240 − 110| = 130°.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q7\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 18, 15 and 8 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"41 seconds\",\"180 seconds\",\"720 seconds\",\"360 seconds\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"LCM(18, 15, 8) = 360 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q8\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Find the simple interest on Rs 10500 at 6% per annum for 4 years.\",\"options\":[\"Rs 2304\",\"Rs 2369\",\"Rs 2602\",\"Rs 2520\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"SI = P × R × T / 100 = 10500 × 6 × 4 / 100 = Rs 2520.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q9\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"3 bells ring at intervals of 6, 18 and 20 seconds. If they ring together now, after how many seconds will they next ring together?\",\"options\":[\"360 seconds\",\"90 seconds\",\"180 seconds\",\"44 seconds\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"LCM(6, 18, 20) = 180 seconds.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q10\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In what ratio must rice at Rs 24/kg be mixed with rice at Rs 72/kg so that the mixture costs Rs 64/kg?\",\"options\":[\"1:5\",\"2:5\",\"24:72\",\"5:1\"],\"yourOption\":1,\"correctOption\":0,\"explanation\":\"Alligation: (cheaper : dearer) = (72 − 64) : (64 − 24) = 1:5.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q11\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The price of an item is first increased by 10% and then decreased by 20%. What is the net percentage change in its price?\",\"options\":[\"12% decrease\",\"11% decrease\",\"14% decrease\",\"13% decrease\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Net factor = (1 + 10/100)(1 - 20/100) = 22/25, so the change is -12%: a 12% decrease.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q12\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"The present ages of A and B are in the ratio 7:5. After 4 years, the ratio will be 25:19. What is A\'s present age?\",\"options\":[\"15 years\",\"25 years\",\"19 years\",\"21 years\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Let ages be 7x and 5x. (7x+4)/(5x+4) = 25/19 gives x = 3; A = 21.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q13\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"If 4x + 29 = 85, what is x?\",\"options\":[\"17\",\"18\",\"14\",\"10\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"4x = 56, so x = 14.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q14\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"Study the table and answer.\\n\\nYear | Produced (units) | Sold (units)\\n2021 | 300 | 280\\n2022 | 250 | 210\\n2023 | 340 | 280\\n2024 | 240 | 190\\n2025 | 130 | 105\\n\\nIn 2023, what percentage of the units produced was sold? (to 2 decimal places)\",\"options\":[\"17.65%\",\"84.85%\",\"82.35%\",\"80.6%\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"280/340 × 100 = 82.35%.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q15\",\"type\":\"MCQ\",\"section\":\"Quantitative\",\"text\":\"In how many ways can a committee of 2 be chosen from 6 people?\",\"options\":[\"12\",\"30\",\"21\",\"15\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"C(6,2) = 15.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q16\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 17th from the left and 11th from the right in a row. How many people are in the row?\",\"options\":[\"28\",\"27\",\"26\",\"29\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 17 + 11 − 1 = 27.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q17\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: D, F, H, J, L, ?\",\"options\":[\"N\",\"P\",\"O\",\"M\"],\"correctOption\":0,\"explanation\":\"Each letter moves 2 places forward.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q18\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Bharat is taller than Kavya. Farhan is taller than Bharat. Jatin is taller than Asha. Kavya is taller than Jatin. Who is the shortest?\",\"options\":[\"Asha\",\"Kavya\",\"Farhan\",\"Bharat\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Chaining the clues: Farhan > Bharat > Kavya > Jatin > Asha. The shortest is Asha.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q19\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 21st from the left and 20th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"42\",\"40\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Total = 21 + 20 − 1 = 40.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q20\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Yash walks 12 m towards the East, then turns right and walks 5 m, then turns right and walks 12 m. How far is Yash from the starting point?\",\"options\":[\"4 m\",\"8 m\",\"5 m\",\"1 m\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Net displacement: 0 m east and 5 m south; distance = √(0² + 5²) = 5 m.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q21\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some cars are flowers. All flowers are phones.\\nConclusion: All cars are phones.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q22\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Nikhil is 18th from the left and 17th from the right in a row. How many people are in the row?\",\"options\":[\"36\",\"33\",\"35\",\"34\"],\"correctOption\":3,\"explanation\":\"Total = 18 + 17 − 1 = 34.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q23\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 31, 27, 1000, 125?\",\"options\":[\"27\",\"31\",\"1000\",\"125\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"31 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q24\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"In a class of 83 students, 50 like cricket, 44 like football and 23 like both. How many like neither?\",\"options\":[\"14\",\"12\",\"35\",\"15\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"83 − (50 + 44 − 23) = 12.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q25\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Asha is 25th from the left and 24th from the right in a row. How many people are in the row?\",\"options\":[\"48\",\"50\",\"47\",\"49\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Total = 25 + 24 − 1 = 48.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q26\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"What comes next: F, J, N, R, V, ?\",\"options\":[\"B\",\"Z\",\"Y\",\"A\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Each letter moves 4 places forward.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q27\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Lokesh is 24th from the left and 16th from the right in a row. How many people are in the row?\",\"options\":[\"41\",\"39\",\"38\",\"40\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Total = 24 + 16 − 1 = 39.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q28\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Which number is the odd one out: 8, 218, 216, 1000?\",\"options\":[\"218\",\"8\",\"1000\",\"216\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"218 — all others are perfect cubes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q29\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"Statements: Some teachers are chairs. All chairs are birds.\\nConclusion: All teachers are birds.\\nDoes the conclusion follow?\",\"options\":[\"The conclusion definitely follows\",\"The conclusion does not follow\",\"The data is contradictory\",\"The conclusion is partly true\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Draw the Venn diagram for the statements: the conclusion fails in at least one possible case.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q30\",\"type\":\"MCQ\",\"section\":\"Logical\",\"text\":\"A man is facing North. He turns right, then turns left, then turns about. Which direction is he facing now?\",\"options\":[\"West\",\"North\",\"East\",\"South\"],\"correctOption\":3,\"explanation\":\"Right = 90° clockwise, left = 90° anticlockwise, about = 180°. Final direction: South.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q31\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘VIVID’.\",\"options\":[\"bright\",\"honest\",\"rough\",\"late\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"‘vivid’ means bright.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q32\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: The workers went ____ strike yesterday.\",\"options\":[\"at\",\"in\",\"for\",\"on\"],\"yourOption\":2,\"correctOption\":3,\"explanation\":\"Correct: The workers went on strike yesterday.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q33\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Unless you (B) do not work hard, (C) you will not (D) succeed.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":2,\"correctOption\":1,\"explanation\":\"‘Unless’ is already negative: ‘work hard’.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q34\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A speech made without preparation\",\"options\":[\"monologue\",\"extempore\",\"sermon\",\"lecture\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A speech made without preparation: extempore.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q35\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘hit the nail on the head’ mean?\",\"options\":[\"make a loud noise\",\"hurt someone badly\",\"describe exactly what is causing a problem\",\"work as a carpenter\"],\"correctOption\":2,\"explanation\":\"‘hit the nail on the head’ means: describe exactly what is causing a problem.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q36\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ENIGMATIC’.\",\"options\":[\"energetic\",\"emphatic\",\"mysterious\",\"erratic\"],\"yourOption\":0,\"correctOption\":2,\"explanation\":\"‘enigmatic’ means mysterious.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q37\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: She is capable ____ handling the pressure.\",\"options\":[\"of\",\"for\",\"at\",\"to\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Correct: She is capable of handling the pressure.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q38\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) Ten kilometres (B) are (C) a long distance (D) to walk.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A distance as one amount: ‘is’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q39\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who is easily deceived\",\"options\":[\"cynical\",\"vigilant\",\"sceptical\",\"gullible\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"A person who is easily deceived: gullible.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q40\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘cost an arm and a leg’ mean?\",\"options\":[\"need hard work\",\"cause an injury\",\"be cheap\",\"be very expensive\"],\"correctOption\":3,\"explanation\":\"‘cost an arm and a leg’ means: be very expensive.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q41\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Choose the word closest in meaning to ‘ALLEVIATE’.\",\"options\":[\"allocate\",\"allude\",\"relieve\",\"alter\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"‘alleviate’ means relieve.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q42\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Fill in the blank: No sooner did she arrive ____ the lights went out.\",\"options\":[\"that\",\"than\",\"when\",\"then\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Correct: No sooner did she arrive than the lights went out.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q43\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"Spot the part of the sentence that has an error:\\n(A) She (B) has (C) a lot of (D) knowledges.\",\"options\":[\"Part A\",\"Part B\",\"Part C\",\"Part D\",\"No error\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘Knowledge’ is uncountable: ‘knowledge’.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q44\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"One word for: A person who spends very little\",\"options\":[\"philanthropist\",\"miser\",\"spendthrift\",\"donor\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"A person who spends very little: miser.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q45\",\"type\":\"MCQ\",\"section\":\"Verbal\",\"text\":\"What does the idiom ‘a drop in the ocean’ mean?\",\"options\":[\"a heavy rain\",\"a sea voyage\",\"a big mistake\",\"a very small amount compared to what is needed\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"‘a drop in the ocean’ means: a very small amount compared to what is needed.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q46\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What does ‘len([1, [2, 3], 4])’ return in Python?\",\"options\":[\"Error\",\"4\",\"3\",\"2\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"The nested list counts as one element.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q47\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which device forwards frames using MAC addresses?\",\"options\":[\"Router\",\"Switch\",\"Modem\",\"Hub\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Switches work at layer 2.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q48\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"The difference between a process and a thread is that threads\",\"options\":[\"have separate address spaces\",\"always run on different machines\",\"share the memory of their process\",\"cannot run in parallel\"],\"correctOption\":2,\"explanation\":\"Threads of one process share its address space.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q49\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which scheduling algorithm can cause starvation of long jobs?\",\"options\":[\"First Come First Served\",\"Round Robin\",\"Shortest Job First\",\"Multilevel with ageing\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Short jobs keep jumping ahead.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q50\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Microservices architecture means\",\"options\":[\"an app built as small independently deployable services\",\"a database type\",\"only front-end code\",\"one large deployable unit\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Each service owns one capability.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q51\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which traversal uses a stack (explicitly or via recursion)?\",\"options\":[\"Depth-first search\",\"Level-order traversal\",\"Dijkstra with a queue\",\"Breadth-first search\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"DFS goes deep first.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q52\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ACID properties of transactions are\",\"options\":[\"Atomicity, Consistency, Isolation, Durability\",\"Accuracy, Concurrency, Integrity, Durability\",\"Atomicity, Concurrency, Isolation, Dependency\",\"Availability, Consistency, Isolation, Durability\"],\"yourOption\":0,\"correctOption\":0,\"explanation\":\"Standard transaction guarantees.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q53\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which testing checks individual functions in isolation?\",\"options\":[\"System testing\",\"Acceptance testing\",\"Load testing\",\"Unit testing\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Smallest testable parts.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q54\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In MS Excel, which function adds a range of cells?\",\"options\":[\"TOTAL\",\"ADD\",\"SUM\",\"COUNT\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"=SUM(A1:A10).\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q55\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Cloud model where you rent virtual machines and manage the OS yourself:\",\"options\":[\"SaaS\",\"IaaS\",\"PaaS\",\"FaaS\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Infrastructure as a Service.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q56\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Gmail is an example of\",\"options\":[\"On-premise software\",\"SaaS\",\"IaaS\",\"PaaS\"],\"yourOption\":1,\"correctOption\":1,\"explanation\":\"Software delivered over the internet.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q57\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"In C, the size of ‘char’ is\",\"options\":[\"2 bytes\",\"depends on the compiler always 8 bytes\",\"4 bytes\",\"1 byte\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"char is defined as one byte.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q58\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"What is a deadlock?\",\"options\":[\"Memory that cannot be freed\",\"A crashed disk\",\"A process that finishes early\",\"Processes waiting forever for resources held by each other\"],\"yourOption\":3,\"correctOption\":3,\"explanation\":\"Circular wait among processes.\",\"marksAwarded\":1,\"marks\":1},{\"id\":\"q59\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"Which normal form removes partial dependencies on a composite key?\",\"options\":[\"2NF\",\"BCNF\",\"3NF\",\"1NF\"],\"correctOption\":0,\"explanation\":\"2NF requires full functional dependency on the whole key.\",\"marksAwarded\":0,\"marks\":1},{\"id\":\"q60\",\"type\":\"MCQ\",\"section\":\"Computer fundamentals\",\"text\":\"ARP is used to find\",\"options\":[\"the IP for a domain\",\"open ports\",\"the MAC address for an IP address\",\"the fastest route\"],\"yourOption\":2,\"correctOption\":2,\"explanation\":\"Address Resolution Protocol.\",\"marksAwarded\":1,\"marks\":1}],\"released\":true,\"answersShown\":true,\"pendingReview\":false}','2026-01-22 23:00:00','2026-01-23 00:00:00'),('724f7380-219a-422a-aa0f-ab4fd57c6846','260c32f9-7de0-4be6-b091-dcd32b1de502','d982eb41-5501-48a5-9ad8-a4b1b2cf69b1','2026-06-03 04:00:00','2026-11-24 19:07:43','2026-06-03 04:28:00',NULL,'2026-06-03 04:00:00',1,0,NULL,4.00,5,'{\"q1\":{\"option\":3},\"q2\":{\"option\":2},\"q3\":{\"option\":1},\"q4\":{\"option\":1},\"q5\":{\"option\":1}}',NULL,'{\"attemptId\":\"724f7380-219a-422a-aa0f-ab4fd57c6846\",\"testId\":\"260c32f9-7de0-4be6-b091-dcd32b1de502\",\"title\":\"TCS NQT Pattern - Practice Set\",\"companyTag\":\"TCS\",\"startedAt\":\"2026-11-24T18:37:43Z\",\"submittedAt\":\"2026-11-24T18:37:42.794785352Z\",\"timeTakenSeconds\":-1,\"score\":4,\"maxScore\":5,\"percent\":80,\"sections\":[{\"name\":\"Numerical Ability\",\"score\":2,\"max\":3,\"correct\":2,\"total\":3},{\"name\":\"Verbal Ability\",\"score\":2,\"max\":2,\"correct\":2,\"total\":2}],\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"section\":\"Numerical Ability\",\"text\":\"A shopkeeper sells an item at 20% profit. If the cost price is Rs 500, what is t