INSERT INTO `prep_tests` (`id`, `college_id`, `title`, `description`, `company_tag`, `level`, `level_order`, `duration_minutes`, `question_count`, `coding_count`, `total_marks`, `definition_json`, `published`, `mode`, `starts_at`, `ends_at`, `branch_ids`, `batch_years`, `shuffle_questions`, `shuffle_options`, `show_answers`, `results_released`, `live_notified_at`, `created_by`, `created_at`, `updated_at`) VALUES ('102a8a4e-af3c-4b9a-a24c-54b8c2528e89',NULL,'Amazon SDE style · Debugging + Coding','Code reasoning and debugging MCQs, then two hard problems. 10 MCQs + 2 coding problems in 105 minutes. Original practice questions modelled on the publicly reported test pattern. Not an official or past paper.','Amazon','HARD',20,105,12,2,30,'{\"title\":\"Amazon SDE style · Debugging + Coding\",\"description\":\"Code reasoning and debugging MCQs, then two hard problems. 10 MCQs + 2 coding problems in 105 minutes. Original practice questions modelled on the publicly reported test pattern. Not an official or past paper.\",\"companyTag\":\"Amazon\",\"level\":\"HARD\",\"order\":20,\"durationMinutes\":105,\"sections\":[{\"name\":\"Code reasoning and debugging\",\"pick\":null,\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"text\":\"What is the value of 41 & 36 (bitwise, on integers)?\",\"options\":[\"28\",\"24\",\"32\",\"34\"],\"answer\":2,\"explanation\":\"41 = 101001₂, 36 = 100100₂ → result 100000₂ = 32.\"},{\"id\":\"q2\",\"type\":\"MCQ\",\"text\":\"What is printed?\\n\\ncount = 0\\nfor i = 1 to 7\\n    for j = i + 1 to 7\\n        count = count + 1\\n    end for\\nend for\\nprint count\",\"options\":[\"49\",\"14\",\"21\",\"28\"],\"answer\":2,\"explanation\":\"Counting the inner iterations gives 21.\"},{\"id\":\"q3\",\"type\":\"MCQ\",\"text\":\"Keys are inserted into an empty binary search tree in this order: 96, 73, 4, 94, 97, 65, 18, 59. What is the preorder traversal?\",\"options\":[\"96 73 4 65 18 59 94 97\",\"97 96 94 73 65 59 18 4\",\"4 18 59 65 73 94 96 97\",\"96 73 4 94 97 65 18 59\"],\"answer\":0,\"explanation\":\"Build the BST, then visit root, left subtree, right subtree.\"},{\"id\":\"q4\",\"type\":\"MCQ\",\"text\":\"Keys are inserted into an empty BST in this order: 28, 96, 81, 45, 76, 32, 88. What is the height of the tree (number of nodes on the longest root-to-leaf path)?\",\"options\":[\"5\",\"4\",\"3\",\"2\"],\"answer\":0,\"explanation\":\"The longest path has 5 nodes.\"},{\"id\":\"q5\",\"type\":\"MCQ\",\"text\":\"What is the value of 59 ^ 24 (bitwise, on integers)?\",\"options\":[\"35\",\"39\",\"42\",\"40\"],\"answer\":0,\"explanation\":\"59 = 111011₂, 24 = 11000₂ → result 100011₂ = 35.\"},{\"id\":\"q6\",\"type\":\"MCQ\",\"text\":\"What is the value of 34 | 6 (bitwise, on integers)?\",\"options\":[\"43\",\"41\",\"38\",\"45\"],\"answer\":2,\"explanation\":\"34 = 100010₂, 6 = 110₂ → result 100110₂ = 38.\"},{\"id\":\"q7\",\"type\":\"MCQ\",\"text\":\"What is the output? (div = integer division)\\n\\nn = 9725\\nc = 0\\nwhile n > 0\\n    c = c + 1\\n    n = n div 10\\nend while\\nprint c\",\"options\":[\"5\",\"3\",\"2\",\"4\"],\"answer\":3,\"explanation\":\"Trace the loop digit by digit.\"},{\"id\":\"q8\",\"type\":\"MCQ\",\"text\":\"Table:\\nEmployee(id, name, dept, salary)\\n1 | Divya | Sales | 90000\\n2 | Irfan | Sales | 35000\\n3 | Amit | IT | 35000\\n4 | Bina | Sales | 35000\\n5 | Hina | HR | 60000\\n6 | Jaya | IT | 45000\\n7 | Ekta | HR | 40000\\n\\nWhat does this query return?\\nSELECT dept FROM Employee GROUP BY dept HAVING COUNT(*) >= 2;  -- how many rows does this return?\",\"options\":[\"2\",\"1\",\"3\",\"0\"],\"answer\":2,\"explanation\":\"Evaluate the query row by row on the table shown.\"},{\"id\":\"q9\",\"type\":\"MCQ\",\"text\":\"Table:\\nEmployee(id, name, dept, salary)\\n1 | Irfan | IT | 50000\\n2 | Amit | Sales | 45000\\n3 | Jaya | Sales | 80000\\n4 | Faiz | Sales | 30000\\n5 | Bina | IT | 55000\\n6 | Gaurav | IT | 40000\\n7 | Ekta | Sales | 80000\\n\\nWhat does this query return?\\nSELECT dept FROM Employee GROUP BY dept HAVING COUNT(*) >= 2;  -- how many rows does this return?\",\"options\":[\"1\",\"3\",\"2\",\"0\"],\"answer\":2,\"explanation\":\"Evaluate the query row by row on the table shown.\"},{\"id\":\"q10\",\"type\":\"MCQ\",\"text\":\"What does this C code print?\\n\\nint x = 4;\\nint y = x++ * 2 + 1;\\nprintf(\\\"%d %d\\\", y, x);\",\"options\":[\"11 5\",\"11 4\",\"9 5\",\"9 4\"],\"answer\":2,\"explanation\":\"x++ uses 4 and then increments x: y = 9, x = 5.\"}]},{\"name\":\"Coding\",\"pick\":null,\"questions\":[{\"id\":\"q11\",\"type\":\"CODING\",\"title\":\"Minimum jumps\",\"text\":\"From index 0 you may jump forward at most a[i] steps from index i. Print the minimum number of jumps to reach the last index, or −1 if it cannot be reached.\\n\\nInput: first line n (1 ≤ n ≤ 10^5); second line n integers (0 to 10^5).\\nOutput: the minimum jumps or -1.\",\"marks\":10,\"explanation\":\"Reference approach: see the standard technique for ‘Minimum jumps’.\",\"starterCode\":{\"python\":\"import sys\\n\\ndata = sys.stdin.read().split()\\n# write your code here\\n\",\"java\":\"import java.util.*;\\nimport java.io.*;\\n\\npublic class Main {\\n    public static void main(String[] args) throws IOException {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        // write your code here\\n    }\\n}\\n\",\"cpp\":\"#include <bits/stdc++.h>\\nusing namespace std;\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    // write your code here\\n    return 0;\\n}\\n\",\"javascript\":\"const data = require(\'fs\').readFileSync(0, \'utf8\').trim().split(/\\\\s+/);\\n// write your code here\\n\"},\"samples\":[{\"input\":\"5\\n2 3 1 1 4\\n\",\"output\":\"2\"},{\"input\":\"5\\n3 2 1 0 4\\n\",\"output\":\"-1\"}],\"tests\":[{\"input\":\"1\\n0\\n\",\"output\":\"0\"},{\"input\":\"2\\n0 1\\n\",\"output\":\"-1\"},{\"input\":\"2562\\n3 3 2 4 2 4 4 2 0 3 4 0 1 0 2 2 2 2 1 3 0 3 4 1 3 0 3 2 1 1 1 0 2 4 0 0 0 1 1 3 4 4 2 1 2 0 3