INSERT INTO `prep_tests` (`id`, `college_id`, `title`, `description`, `company_tag`, `level`, `level_order`, `duration_minutes`, `question_count`, `coding_count`, `total_marks`, `definition_json`, `published`, `mode`, `starts_at`, `ends_at`, `branch_ids`, `batch_years`, `shuffle_questions`, `shuffle_options`, `show_answers`, `results_released`, `live_notified_at`, `created_by`, `created_at`, `updated_at`) VALUES ('3a2865c7-79c3-4a78-a746-a28d65258112',NULL,'Adobe style · Aptitude, Technical + Coding','Short aptitude and technical sections, then two hard problems. 20 MCQs + 2 coding problems in 90 minutes. Original practice questions modelled on the publicly reported test pattern. Not an official or past paper.','Adobe','HARD',18,90,22,2,40,'{\"title\":\"Adobe style · Aptitude, Technical + Coding\",\"description\":\"Short aptitude and technical sections, then two hard problems. 20 MCQs + 2 coding problems in 90 minutes. Original practice questions modelled on the publicly reported test pattern. Not an official or past paper.\",\"companyTag\":\"Adobe\",\"level\":\"HARD\",\"order\":18,\"durationMinutes\":90,\"sections\":[{\"name\":\"Aptitude\",\"pick\":null,\"questions\":[{\"id\":\"q1\",\"type\":\"MCQ\",\"text\":\"A can do a job in 45 days and B in 36 days. They work together for 2 days, then B leaves. In how many more days will A finish the job?\",\"options\":[\"81/2 days\",\"162/5 days\",\"40 days\",\"83/2 days\"],\"answer\":0,\"explanation\":\"In 2 days they do 1/10 of the work; 9/10 is left, which A does in 9/10 × 45 = 81/2 days.\"},{\"id\":\"q2\",\"type\":\"MCQ\",\"text\":\"What are the roots of x² - 3x + 2 = 0?\",\"options\":[\"-2 and 1\",\"1 and 2\",\"2 and 3\",\"-2 and -1\"],\"answer\":1,\"explanation\":\"Sum of roots = 3, product = 2: the roots are 1 and 2.\"},{\"id\":\"q3\",\"type\":\"MCQ\",\"text\":\"What is the smaller angle between the hour and minute hands of a clock at 5:40?\",\"options\":[\"290°\",\"75°\",\"70°\",\"90°\"],\"answer\":2,\"explanation\":\"Angle = |30H − 5.5M| = |150 − 220| = 70°.\"},{\"id\":\"q4\",\"type\":\"MCQ\",\"text\":\"If today is Friday, what day of the week will it be after 195 days?\",\"options\":[\"Wednesday\",\"Monday\",\"Tuesday\",\"Thursday\"],\"answer\":3,\"explanation\":\"195 mod 7 = 6; Friday + 6 days = Thursday.\"},{\"id\":\"q5\",\"type\":\"MCQ\",\"text\":\"The average age of 10 students is 54 years. When the teacher\'s age is included, the average decreases by 2 years. What is the teacher\'s age?\",\"options\":[\"33\",\"24\",\"32\",\"38\"],\"answer\":2,\"explanation\":\"New total = 52 × 11 = 572; old total = 540; teacher = 32.\"},{\"id\":\"q6\",\"type\":\"MCQ\",\"text\":\"In a code language, HAMMER is written as VIQQEL. How is CAMERA written in that code?\",\"options\":[\"EQIVEE\",\"FWJRFH\",\"EVIQEG\",\"GEQIVE\"],\"answer\":2,\"explanation\":\"Each letter is shifted +4 and the word is then reversed.\"},{\"id\":\"q7\",\"type\":\"MCQ\",\"text\":\"Which number is the odd one out: 57, 117, 54, 72?\",\"options\":[\"54\",\"117\",\"72\",\"57\"],\"answer\":3,\"explanation\":\"57 — all others are multiples of 9.\"},{\"id\":\"q8\",\"type\":\"MCQ\",\"text\":\"Meera is the father of Nikhil. Nikhil is the sister of Bharat. How is Meera related to Bharat?\",\"options\":[\"Uncle\",\"Father\",\"Grandfather\",\"Brother\"],\"answer\":1,\"explanation\":\"Bharat is Nikhil\'s sibling, so Meera is Bharat\'s father too.\"},{\"id\":\"q9\",\"type\":\"MCQ\",\"text\":\"Isha\'s father is the only son of Pooja\'s father. Pooja is Isha\'s ____ if Pooja is female.\",\"options\":[\"Cousin\",\"Sister\",\"Aunt\",\"Mother\"],\"answer\":2,\"explanation\":\"Pooja is a daughter of Isha\'s grandfather and not Isha\'s mother (his father is the only son), so she is Isha\'s aunt.\"},{\"id\":\"q10\",\"type\":\"MCQ\",\"text\":\"If 9 ⊕ 8 = 10; 2 ⊕ 6 = 18, then 6 ⊕ 9 = ?\",\"options\":[\"15\",\"16\",\"18\",\"13\"],\"answer\":0,\"explanation\":\"a ⊕ b = (a − b)² + a; so 6 ⊕ 9 = 15.\"}]},{\"name\":\"Technical\",\"pick\":null,\"questions\":[{\"id\":\"q11\",\"type\":\"MCQ\",\"text\":\"A load balancer\",\"options\":[\"stores session data permanently\",\"compiles code\",\"encrypts databases\",\"spreads requests across several servers\"],\"answer\":3,\"explanation\":\"Improves availability and throughput.\"},{\"id\":\"q12\",\"type\":\"MCQ\",\"text\":\"RAM is\",\"options\":[\"a type of ROM\",\"permanent storage\",\"an output device\",\"volatile memory\"],\"answer\":3,\"explanation\":\"Contents are lost when power is off.\"},{\"id\":\"q13\",\"type\":\"MCQ\",\"text\":\"A context switch is\",\"options\":[\"changing the user\",\"restarting the OS\",\"saving one process\'s state and loading another\'s\",\"switching the network\"],\"answer\":2,\"explanation\":\"The CPU moves between processes.\"},{\"id\":\"q14\",\"type\":\"MCQ\",\"text\":\"Which traversal of a BST gives keys in sorted order?\",\"options\":[\"Inorder\",\"Postorder\",\"Level order\",\"Preorder\"],\"answer\":0,\"explanation\":\"Left, root, right.\"},{\"id\":\"q15\",\"type\":\"MCQ\",\"text\":\"What is the decimal value of hexadecimal 92?\",\"options\":[\"146\",\"140\",\"155\",\"137\"],\"answer\":0,\"explanation\":\"92₁₆ = 146.\"},{\"id\":\"q16\",\"type\":\"MCQ\",\"text\":\"What is printed?\\n\\ncount = 0\\nfor i = 1 to 6\\n    for j = 1 to i\\n        count = count + 1\\n    end for\\nend for\\nprint count\",\"options\":[\"15\",\"21\",\"36\",\"27\"],\"answer\":1,\"explanation\":\"Counting the inner iterations gives 21.\"},{\"id\":\"q17\",\"type\":\"MCQ\",\"text\":\"What is the output? (div = integer division)\\n\\nn = 9984\\nr = 0\\nwhile n > 0\\n    r = r * 10 + (n mod 10)\\n    n = n div 10\\nend while\\nprint r\",\"options\":[\"5268\",\"5290\",\"4899\",\"4486\"],\"answer\":2,\"explanation\":\"Trace the loop digit by digit.\"},{\"id\":\"q18\",\"type\":\"MCQ\",\"text\":\"Starting with an empty queue (push = enqueue, pop = dequeue), these operations run: push(40), pop(), push(10), push(44), pop(), push(20), pop(), push(33), pop(). What is at the front now?\",\"options\":[\"10\",\"44\",\"33\",\"40\"],\"answer\":2,\"explanation\":\"Simulating the operations, the front element is 33.\"},{\"id\":\"q19\",\"type\":\"MCQ\",\"text\":\"Given the function f(n) = 0 if n == 0 else n + f(n - 1), what is f(4)?\",\"options\":[\"12\",\"7\",\"8\",\"10\"],\"answer\":3,\"explanation\":\"Expanding the recursion gives f(4) = 10.\"},{\"id\":\"q20\",\"type\":\"MCQ\",\"text\":\"Table:\\nEmployee(id, name, dept, salary)\\n1 | Chetan | IT | 70000\\n2 | Faiz | Sales | 65000\\n3 | Amit | Sales | 60000\\n4 | Irfan | IT | 35000\\n5 | Ekta | IT | 75000\\n6 | Divya | IT | 90000\\n7 | Hina | IT | 90000\\n\\nWhat does this query return?\\nSELECT COUNT(*) FROM Employee WHERE salary > 50000;\",\"options\":[\"5\",\"6\",\"7\",\"8\"],\"answer\":1,\"explanation\":\"Evaluate the query row by row on the table shown.\"}]},{\"name\":\"Coding\",\"pick\":null,\"questions\":[{\"id\":\"q21\",\"type\":\"CODING\",\"title\":\"Trapping rain water\",\"text\":\"Bars of width 1 have the given heights. Print how many units of water are trapped between them after rain.\\n\\nInput: first line n (1 ≤ n ≤ 10^5); second line n heights (0 to 10^5).\\nOutput: the trapped water.\",\"marks\":10,\"explanation\":\"Reference approach: see the standard technique for ‘Trapping rain water’.\",\"starterCode\":{\"python\":\"import sys\\n\\ndata = sys.stdin.read().split()\\n# write your code here\\n\",\"java\":\"import java.util.*;\\nimport java.io.*;\\n\\npublic class Main {\\n    public static void main(String[] args) throws IOException {\\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\\n        // write your code here\\n    }\\n}\\n\",\"cpp\":\"#include <bits/stdc++.h>\\nusing namespace std;\\n\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    // write your code here\\n    return 0;\\n}\\n\",\"javascript\":\"const data = require(\'fs\').readFileSync(0, \'utf8\').trim().split(/\\\\s+/);\\n// write your code here\\n\"},\"samples\":[{\"input\":\"12\\n0 1 0 2 1 0 1 3 2 1 2 1\\n\",\"output\":\"6\"},{\"input\":\"6\\n4 2 0 3 2 5\\n\",\"output\":\"9\"}],\"tests\":[{\"input\":\"1\\n5\\n\",\"output\":\"0\"},{\"input\":\"3\\n1 2 3\\n\",\"output\":\"0\"},{\"input\":\"921\\n11 13 2 8 17 13 18 0 20 7 7 20 10 0 3 18 16 10 13 9 9 18 9 8 8 2 11 19 7 19 4 7 6 8 17 0 2 12 8 13 3 20 12 18 11 6 12 9 0 18 12 0 6 7 15 6 19 10 1 12 20 16 18 8 11 19 16 1 11 6 0 13 13 17 4 20 14 5 18 19 14 18 17 15 0 0 5 20 5 12 14 11 3 5 19 16 5 19 5 9 16 0 15 15 2 6 6 3 6 19 13 18 6 16 1 17 0 9 14 18 7 17 11 0 14 9 19 7 9 1 19 4 10 19 14 19 16 10 10 0 12 6 8 12 8 19 10 16 11 19 4 15 8 13 20 0 5 17 7 15 18 20 3 14 16 13 19 10 8 10 11 14 17 12 0 8 2 7 10 17 19 7 6 1 1 7 20 6 15 3 13 10 18 6 0 17 11 13 20 20 6 19 16 6 5 19 0 0 0 3 3 19 17 12 1 0 9 12 11 4 1 20 4 16 4 14 18 1 1 20 7 6 18 1 5 9 13 15 13 19 0 4 12 15 3 16 20 15 9 19 4 12 2 16 15 2 2 0 13 5 0 10 12 19 18 12 15 2 12 2 12 18 19 8 12 15 17 6 16 0 8 14 18 13 6 9 0 9 3 7 10 16 19 19 15 18 5 9 10 15 16 18 5 8 15 10 2 14 1 18 13 6 13 13 5 12 18 12 2 6 8 2 10 7 7 5 17 5 17 17 20 8 15 3 8 1 5 7 8 16 2 13 17 0 0 18 18 5 5 12 14 18 7 2 8 6 0 17 20 4 20 6 17 7 15 8 0 3 20 7 16 7 3 18 20 17 5 19 10 9 19 3 8 17 12 16 11 16 17 8 11 19 11 8 5 17 1 20 10 8 4 10 20 3 9 12 19 16 3 6 19 15 1 11 16 6 15 2 19 15 8 15 16 18 7 5 6 8 6 8 18 9 19 8 11 18 12 11 16 17 5 16 6 13 9 2 3 1 18 14 6 7 9 9 12 17 18 17 2 1 17 18 5 20 11 0 9 9 19 13 0 18 8 11 14 7 2 10 4 3 3 3 4 8 9 18 11 13 6 19 15 11 1 12 13 14 7 4 11 6 15 9 18 8 19 0 19 6 13 11 18 8 17 17 20 11 9 2 16 8 8 6 8 16 19 1 11 4 20 18 0 6 7 15 14 6 14 4 10 2 14 11 4 5 8 18 10 15 13 14 7 10 11 16 20 16 14 0 19 6 4 17 12 19 7 18 5 10 3 2 1 20 1 2 16 16 1 1 1 1 11 7 6 13 14 7 17 18 15 18 8 0 18 17 16 15 10 20 3 14 3 10 20 13 3 10 15 4 16 9 18 3 18 8 6 1 18 20 5 11 2 18 18 8 16 0 2 0 0 2 2 0 19 14 0 1 1 3 11 11 9 1 13 13 10 14 6 10 3 15 6 11 6 18 20 19 16 7 15 8 9 6 3 6 3 1 1 8 6 16 0 17 10 7 6 5 4 8 0 19 12 3 8 8 9 12 20 